Object.assign(window.__SYN,{"c:弦+细+滑": {"o": "弦细滑脉总起来主肝旺、阴血虚、痰湿内蕴三类基本病机，并由此衍生肝胃不和、痰火、本虚标实等复合病机。弦应肝，主肝气偏亢、肝火上逆；细应阴血，主阴血亏耗；滑应痰湿，主痰浊内阻。三者合见，说明肝旺与阴血不足并存，痰湿内滞其间，形成本虚标实、虚实夹杂之局。若肝旺犯胃，则见肝胃不和；若肝火炼液，则成痰火；若阴血亏虚明显，则成本虚标实。各证候之间相互关联，总以肝旺、阴伤、痰湿为枢机，故临床可见咳喘、脘痛、不寐、痫症、淋证等多种病证。", "c": [{"name": "主阴血虚", "desc": "细脉主阴血不足，原文屡言细主血亏、阴伤、阴分不足、营虚。如细主血亏、细为阴伤、产后百脉空虚、左细为血虚、阴血内损，皆以细示阴血亏耗，故弦细滑脉兼主阴血虚。"}, {"name": "主痰湿", "desc": "滑脉主痰湿内蕴，原文多称滑主湿痰、痰浊、痰饮、痰聚。如滑主湿痰、滑主痰浊、滑主痰饮、滑为痰聚、滑乃痰聚，皆以滑示痰湿内阻，故弦细滑脉所主病机以痰湿为要。"}, {"name": "主肝胃不和", "desc": "弦主肝郁气逆，滑主痰湿，细示阴伤，合见则肝气犯胃、胃失和降。如胁痛胀、不思食，肝厥犯胃、脘痛哕吐，木来侮土、水饮停中，肝木侮土、饮食不归正化，皆示肝胃失调、痰气交阻之机。"}, {"name": "主痰火", "desc": "弦为肝火，滑为痰浊，细为阴伤，合见则痰火交炽。如肝火挟痰内阻、七情怫郁、五火烁痰、郁火挟痰、肝阳挟痰热上阻清道，皆以弦滑示痰火互结、气机窒塞，故弦细滑脉主痰火为病。"}, {"name": "主本虚标实", "desc": "细主阴血亏虚，弦滑主肝旺痰湿，合见则正虚与邪实错杂。如产后百脉空虚、湿温弥漫，肺脾肾三经皆亏、痰饮内扰，营虚痰凝，血虚夹痰，皆示本虚标实、虚实夹杂之病机。"}], "n": {"主阴血虚": 1, "主痰湿": 1, "主肝胃不和": 4, "主痰火": 4, "主本虚标实": 15}, "a": {"1999": "主本虚标实", "2075": "主本虚标实", "2078": "主本虚标实", "2082": "主本虚标实", "4807": "主痰火", "5151": "主肝胃不和", "6148": "主肝胃不和", "7675": "主痰火", "8697": "主本虚标实", "8737": "主肝胃不和", "8739": "主肝胃不和", "8754": "主本虚标实", "8778": "主本虚标实", "8792": "主本虚标实", "8812": "主本虚标实", "10948": "主本虚标实", "10956": "主本虚标实", "10998": "主本虚标实", "11033": "主本虚标实", "11069": "主本虚标实", "11278": "主阴血虚", "13338": "主痰火", "13892": "主痰火", "16491": "主本虚标实", "17059": "主痰湿"}, "t": 25, "np": 0}, "c:弦+滑+浮": {"o": "浮弦滑脉总属外邪、痰饮、风阳相互搏结之象。浮主表、主风，弦主饮、主肝风、主痛，滑主痰湿、主食积，三脉相合，多示外邪引动内饮，或风痰上扰，或风邪夹食，或阴虚痰实。其病机核心为'邪实壅阻'，或外寒内饮，或风温引动宿饮，或风阳挟痰上逆，或风暑夹食，或妊娠感风。各段虽病证不同，然皆以浮弦滑为共同脉象，反映邪气在表、在肺、在肝、在胃，痰饮风食交阻为患。其中浮为外邪之标志，弦为饮与风之特征，滑为痰食之征，三者相兼，提示病位较广，病情多实，治当疏解外邪、温化痰饮、息风降火、导滞和胃，或兼顾下元，随证施治。", "c": [{"name": "主外邪束表", "desc": "浮脉主表，弦主风邪，滑主痰湿。原文如321段'暴寒外束'、328段'风温外袭'、16092段'路受风邪'、16459段'兼受风邪'，均见浮弦滑并见，提示外邪袭表，卫阳被遏，肺气失宣，故见寒热、头痛、鼻塞、咳嗽等症。"}, {"name": "主风痰上扰", "desc": "浮弦为风阳上扰，滑为痰浊内盛。13384、13780、13969段均见'猝仆于地'，脉浮弦以滑，乃风痰上逆、气火并升所致，治以息风降火、顺气蠲痰，属风痰闭窍之候。"}, {"name": "主风邪夹食", "desc": "浮主外邪，弦主少阳，滑主痰食。16092段'风暑夹食'、16459段'饮食不节，兼受风邪'，脉浮弦滑，症见寒热而呕、胸腹贲响、食入疼胀，为外风引动内滞，肺胃失和之机。"}, {"name": "主阴虚痰实", "desc": "右寸关弦滑而浮，左关尺细软无神，为阴虚于下、痰实于上、微兼客热之候。14475段痰嗽喘逆、便秘不眠、微热口干，年逾六旬，脉象合示下虚上实，攻补皆难偏任。"}, {"name": "主妊娠感风", "desc": "浮为感风之征，弦滑主孕。8100段'感风咳嗽，怀孕在身'，脉弦滑而浮，示外风袭肺致咳，而脉之弦滑为胎孕之象，故治咳须顾胎，勿犯其下。"}], "n": {"主外邪束表": 2, "主风痰上扰": 3, "主风邪夹食": 2, "主阴虚痰实": 2, "主妊娠感风": 1}, "a": {"321": "主外邪束表", "328": "主外邪束表", "8100": "主妊娠感风", "13384": "主风痰上扰", "13780": "主风痰上扰", "13969": "主风痰上扰", "14475": "主阴虚痰实", "14987": "主阴虚痰实", "16092": "主风邪夹食", "16459": "主风邪夹食"}, "t": 10, "np": 0}, "c:沉+涩": {"o": "沉涩脉总属里证，以气血运行不畅为核心病机。沉主病在里，涩主血行迟滞、津伤或湿阻。其病机有虚实两端：实者多气滞血瘀、痰湿内阻、郁热内伏、寒湿痹阻、气逆不降，皆因邪阻脉道，气血壅滞；虚者多里虚精血亏耗，脉道不充而涩。各类之间常相互兼夹，如气滞血瘀可兼痰湿，郁热可兼血瘀，虚中可夹实。临床须结合脉之有力无力及兼脉兼症，辨其虚实寒热，不可一概作虚寒论。", "c": [{"name": "主气滞血瘀", "desc": "沉主病在里，涩主血行迟滞。原文多见气郁、血瘀、症瘕、经闭、积聚等，如气郁脉沉涩、瘀血内结、少腹满胀、舌苔黄暗等，皆因气血壅滞、脉道不利，故沉涩并见。"}, {"name": "主痰湿内阻", "desc": "沉涩亦主痰湿壅遏气机。原文如肺脉沉涩为风凉湿气遏内热、脉沉涩模糊为湿邪内阻、痰热窒塞气分等，皆因湿痰阻滞，气血运行不畅，脉道涩滞，故见沉涩。"}, {"name": "主里虚精血亏", "desc": "沉涩无力或按久衰者，主里虚、阴血不足、精血枯竭。原文如虚劳脉沉涩两尺甚为伤精、内伤噎隔左寸沉涩心血枯、尺脉沉涩阴精内竭等，皆因精血亏少，脉道不充而涩。"}, {"name": "主郁热内伏", "desc": "沉涩非尽虚寒，亦有痼热郁结者。原文如脉沉而涩重取似数，为郁热内伏；瘀血湿热互结发黄，脉沉涩有力；痰热为补药所遏，脉沉涩。皆因热郁气滞，血行不畅，故脉沉涩。"}, {"name": "主寒湿痹阻", "desc": "沉涩主寒湿痰瘀深伏筋骨、经脉不利。原文如痹证风湿寒三气杂合、脉沉涩为邪入阴分气血痹阻；寒积腹痛脉沉涩宜宣通中气；风淫湿著、脉沉涩无力等，皆寒湿凝滞之象。"}, {"name": "主气逆不降", "desc": "沉涩亦主气机郁滞、升降失常。原文如肺脉沉涩为气郁不降致呃逆、倒经咳血气促、腹满气冲呛咳等，皆因气滞血涩，肺胃之气不降，故脉沉涩。"}], "n": {"主气滞血瘀": 29, "主痰湿内阻": 14, "主里虚精血亏": 12, "主郁热内伏": 7, "主寒湿痹阻": 6, "主气逆不降": 4}, "a": {"1078": "主里虚精血亏", "1441": "主气滞血瘀", "3040": "主里虚精血亏", "3594": "主郁热内伏", "3595": "主郁热内伏", "3647": "主气滞血瘀", "3669": "主里虚精血亏", "3687": "主痰湿内阻", "3691": "主痰湿内阻", "3705": "主郁热内伏", "3707": "主寒湿痹阻", "3946": "主郁热内伏", "4026": "主气滞血瘀", "4249": "主里虚精血亏", "5975": "主气滞血瘀", "6269": "主气滞血瘀", "6723": "主气逆不降", "7125": "主气滞血瘀", "7681": "主气滞血瘀", "8405": "主痰湿内阻", "8476": "主里虚精血亏", "9046": "主气滞血瘀", "11367": "主郁热内伏", "11444": "主气滞血瘀", "11511": "主痰湿内阻", "12189": "主气滞血瘀", "12190": "主气滞血瘀", "12212": "主气逆不降", "12355": "主寒湿痹阻", "12452": "主痰湿内阻", "12617": "主痰湿内阻", "12691": "主痰湿内阻", "12994": "主痰湿内阻", "13239": "主痰湿内阻", "13734": "主里虚精血亏", "13770": "主痰湿内阻", "13958": "主痰湿内阻", "14130": "主痰湿内阻", "14423": "主痰湿内阻", "14861": "主里虚精血亏", "16415": "主气滞血瘀", "16609": "主气滞血瘀", "16929": "主气滞血瘀", "16994": "主气滞血瘀", "17030": "主里虚精血亏", "17103": "主气滞血瘀", "17157": "主气逆不降", "17167": "主寒湿痹阻", "17175": "主里虚精血亏", "17209": "主气滞血瘀", "17407": "主里虚精血亏", "18659": "主气滞血瘀", "18678": "主气滞血瘀", "18693": "主气滞血瘀", "19052": "主寒湿痹阻", "19372": "主气逆不降", "22743": "主寒湿痹阻", "22819": "主气滞血瘀", "23294": "主气滞血瘀", "23321": "主气滞血瘀", "23489": "主气滞血瘀", "23713": "主气滞血瘀", "24009": "主郁热内伏", "24298": "主气滞血瘀", "24302": "主郁热内伏", "24617": "主气滞血瘀", "24721": "主里虚精血亏", "24877": "主气滞血瘀", "24905": "主里虚精血亏", "24943": "主气滞血瘀", "25069": "主寒湿痹阻", "25513": "主痰湿内阻"}, "t": 72, "np": 0}, "pc:左+弦+沉": {"o": "左·弦沉脉总以沉、弦二象合见为特征，沉主里、主下焦，弦主郁、主饮、主肝木。其总病机为肝郁气滞、水饮内停，并可兼化火、兼痰、兼瘀、兼湿热积滞，或兼肾虚不纳。从所收42段看，单纯主饮者如饮泛咳呛、气喘；主郁者如腹胁虚胀、胸膈窒闷；郁久化火则见胁疼、便燥、头晕、厥证；气郁津凝则痰积，见痰块、痞塞；气滞血瘀则见癥瘕、腰疼；兼湿热积滞则见滞下、里急后重；兼肾虚不纳则见喘急起坐。各类之间相互关联：肝郁气滞为共同基础，气郁可化火、生痰、致瘀，亦可横逆犯胃、下及肾元。故左弦沉脉虽主里主郁，但须结合兼脉（如数、滑、涩、牢、洪实）及左右分部，以辨其郁、火、痰、瘀、虚之侧重。", "c": [{"name": "主饮", "desc": "沉弦脉主饮邪内停。沉主里、主下焦，弦为饮。如原文“脉沉弦，弦为饮”，饮泛咳呛、动则气喘，乃下虚无以制上、中虚易于化饮；又“左脉沉弦，右脉浮弦，升降失司，痰饮斯聚”，皆因水饮内停、气机不畅而脉见沉弦。"}, {"name": "主郁", "desc": "沉弦脉主气机郁滞。沉主里，弦主郁，如“沉弦为郁”“沉则气滞，弦则木郁”。肝气郁结，疏泄失职，可见腹胁虚胀、胸膈窒闷、嗳逆吐酸等症；郁久可化火、横逆犯胃，故脉沉弦为肝郁气滞之典型表现。"}, {"name": "主肝火", "desc": "沉弦脉主肝郁化火。沉为里，弦为肝，若沉弦有力或兼数，则示肝经气郁火盛。如“左部沉弦有力，知系肝经气郁火盛”，症见胁疼、便燥、头晕疼、心惕肢楚；又“左寸关沉弦而横”，为水亏营弱、龙雷之火并发，肝阳上冒致厥。"}, {"name": "主痰积", "desc": "沉弦脉主痰积内结。沉弦主气郁，气郁则津液聚而为痰，痰气交阻，积于胸膈脘腹。如“左手沉弦，右手关部独见沉滑”，为肝郁气滞、胃中胶痰纠结；又“左关沉弦，右关沉滑”，为气与痰并、挟块攻痛，肝木侮土。"}, {"name": "主瘀血", "desc": "沉弦脉主瘀血内停。沉弦主气滞，气滞则血行不畅，瘀血内结。如“左脉沉弦，右脉沉涩”，为肝郁气结、瘀血内停，产后恶露少、少腹胀满疼硬；又“左部沉弦，右部沉牢”，为肝肾经络气血瘀滞不通，腰疼数年不愈。"}, {"name": "主虚损", "desc": "沉弦脉主虚损，尤以肾虚不纳、水亏营弱为要。沉主里、主下焦，弦为气逆或肝阳。如“右弦左沉，为肾气不收”，老年咳喘、卧则气冲；又“左寸关沉弦而横”，为水亏营弱、龙雷并发，治宜滋水潜阳。"}, {"name": "主湿热积滞", "desc": "沉弦脉主湿热积滞壅遏肠道。沉弦主气滞，若兼滑数则示湿热积滞。如“左脉沉弦，右脉滑数”，滞下里急后重、下稠黏紫黑血、口渴胸膈焦辣，为湿热积滞胶固肠道、气血壅滞；又“左手沉弦，右手滑大”，为肝郁而胃中痰食积滞。"}], "n": {"主饮": 7, "主郁": 7, "主肝火": 12, "主痰积": 6, "主瘀血": 5, "主虚损": 1, "主湿热积滞": 4}, "a": {"333": "主饮", "908": "主虚损", "2903": "主郁", "2906": "主郁", "3510": "主湿热积滞", "3528": "主郁", "5278": "主饮", "6182": "主湿热积滞", "6477": "主湿热积滞", "7966": "主郁", "10425": "主肝火", "11339": "主郁", "11357": "主郁", "11382": "主郁", "11386": "主肝火", "11434": "主肝火", "11439": "主瘀血", "11442": "主湿热积滞", "11448": "主肝火", "11449": "主肝火", "11454": "主痰积", "11455": "主痰积", "11477": "主痰积", "11506": "主肝火", "12507": "主饮", "12511": "主饮", "12528": "主饮", "12740": "主痰积", "15963": "主痰积", "16890": "主饮", "16999": "主肝火", "17089": "主肝火", "20064": "主肝火", "20262": "主瘀血", "20518": "主瘀血", "20621": "主痰积", "20679": "主肝火", "20680": "主肝火", "20681": "主肝火", "20748": "主瘀血", "20749": "主瘀血", "24775": "主饮"}, "t": 42, "np": 0}, "pc:右+数+洪": {"o": "右·数洪脉总以热盛为核心，洪为热盛，数为热急，右脉候肺胃气分。所主病机涵盖肺胃热盛、痰饮积热、湿热壅盛、燥火热炽、郁火痰积、阴伤火旺、气分热盛、血分热盛等。各类之间相互关联：肺胃热盛可炼液为痰，形成痰饮积热；湿热壅盛多兼痰饮；燥火热炽易伤阴津，致阴伤火旺；郁火痰积为痰火交阻；气分热盛与血分热盛则依左右脉位分属。总因热邪壅遏，或兼痰、湿、燥、郁、虚，故脉见洪数，临床须结合兼脉及部位辨治。", "c": [{"name": "主肺胃热盛", "desc": "右脉洪数，洪为热盛，数为热急，右脉候肺胃。原文多见肺热失音、肺火咳嗽、阳明热盛、胃火刑金等，如“右脉洪数有力，金实无声”“右寸洪数，肺经热壅”，皆因热邪壅遏肺胃气分，故脉洪数。"}, {"name": "主痰饮积热", "desc": "洪数主热，兼滑主痰，饮聚化热。原文有“右脉洪数，为积痰在肺之征”“洪数而滑，肺热痰结”“本有饮聚，小便不长”，说明痰饮内停，郁而化热，热与饮搏，脉见洪数。"}, {"name": "主湿热壅盛", "desc": "洪数为热，濡数为湿，湿热交蒸。原文见“右脉洪数，湿热下注”“六脉洪数，湿热者”“右脉洪数，酒热伤胃”，皆因湿与热合，壅滞气分或下注，故脉洪数。"}, {"name": "主燥火热炽", "desc": "洪数为燥火之征，燥热伤气耗阴。原文“燥痰之脉必洪数”“洪大数疾，燥火加临”“右脉洪数，燥伤气分”，说明燥热内炽，鼓动血脉，故脉洪数。"}, {"name": "主郁火痰积", "desc": "右脉濡数，左脉洪数，濡主湿，数主热，洪为火盛。原文“郁火痰积症也”，因忧思伤脾肺，饮食不化，积而生痰，郁而化火，痰火壅盛，故脉洪数。"}, {"name": "主阴伤火旺", "desc": "左脉细小，右脉洪数，细为阴伤，洪数为火旺。原文“阴津大伤，燥火未退”“阴伤火旺，少阴不足，阳明有余”，说明阴液亏虚，虚火亢盛，脉见洪数。"}, {"name": "主气分热盛", "desc": "右脉洪数，右候气分，洪数为热盛。原文“右脉洪数，热在气”“右脉洪数，肠胃气热”“右脉洪数，病在阳明”，皆因热邪弥漫气分，故脉洪数。"}, {"name": "主血分热盛", "desc": "左脉洪数，左候血分，洪数为热盛。原文“左脉洪数，热在血”“左脉洪数，燥伤于血”“右脉洪数，肺胃大肠血热”，说明热入血分，灼伤阴血，故脉洪数。"}], "n": {"主肺胃热盛": 16, "主痰饮积热": 3, "主湿热壅盛": 8, "主燥火热炽": 3, "主郁火痰积": 2, "主阴伤火旺": 1, "主气分热盛": 6, "主血分热盛": 1}, "a": {"3437": "主痰饮积热", "5403": "主肺胃热盛", "5404": "主肺胃热盛", "5415": "主痰饮积热", "5420": "主湿热壅盛", "5526": "主湿热壅盛", "5539": "主痰饮积热", "5542": "主肺胃热盛", "6188": "主郁火痰积", "6483": "主郁火痰积", "10825": "主阴伤火旺", "11228": "主肺胃热盛", "13402": "主肺胃热盛", "13886": "主肺胃热盛", "16353": "主气分热盛", "18197": "主气分热盛", "18457": "主肺胃热盛", "19788": "主湿热壅盛", "24636": "主肺胃热盛", "24656": "主肺胃热盛", "24657": "主气分热盛", "24659": "主气分热盛", "24661": "主血分热盛", "24681": "主肺胃热盛", "24697": "主肺胃热盛", "24702": "主肺胃热盛", "24720": "主气分热盛", "24732": "主肺胃热盛", "24746": "主气分热盛", "24779": "主燥火热炽", "24814": "主肺胃热盛", "24866": "主肺胃热盛", "24937": "主燥火热炽", "24938": "主燥火热炽", "24948": "主湿热壅盛", "24949": "主湿热壅盛", "24989": "主湿热壅盛", "25034": "主湿热壅盛", "25090": "主湿热壅盛", "25094": "主肺胃热盛"}, "t": 40, "np": 0}, "c:大+散": {"o": "散大脉总属正气耗散、阳不内守之候，其核心病机为“散”与“大”并见，示气机不能收敛。具体可分：气散阳脱者，脉散大无伦，伴汗多喘喝、面赤戴阳，为亡阳危候；气血耗伤者，脉大而散弱，见于劳倦、失血、营阴亏虚；中气虚寒者，脉散大无力，主中气不足、摄纳无权；元气虚散兼瘀者，脉散大而重取弦小长，当先补后逐；热盛津伤者，脉散大见于温病汗多，为气阴两耗；正虚毒陷者，脉散大而兼濡小，主气血两败。诸类皆以正虚为本，或阳脱、或气耗、或津伤、或血亏，其脉形散漫不收，总因元气不能固摄，故治多取益气敛阴、回阳固脱，忌纯用攻伐。", "c": [{"name": "主气散阳脱", "desc": "散大脉为阳气外泄、元气涣散之象。原文如“汗多脉散大，喘喝欲脱”（24380）、“脉散大无伦，面赤戴阳”（16105）、“六脉散大，为汗多亡阳”（16123），皆因大汗、误治或久病致阳不内守，虚阳浮越，故脉形散漫无根，主亡阳危候。"}, {"name": "主气血耗伤", "desc": "散大脉亦主气血亏耗、营阴不足。如“脉弦大散弱，左大为甚”（3692）为劳倦感寒、气耗血伤；“女子脉大而散”（3729）为营阴先亏、气不收敛；“脉大而散为气实血虚”（21653），皆示气血不能内守，脉道松弛而散大。"}, {"name": "主中气虚寒", "desc": "散大而无力，主中气不足、虚寒内生。如遗尿脉“脉见散大，中气虚寒”（24641），治以补中益气汤（24642）；产后“脉愈大，继而散大”（16230）为胃气涣散、虚阳浮越，皆因中焦虚馁，气不摄纳，故脉散大不收。"}, {"name": "主元气虚散兼瘀", "desc": "散大脉可示元气虚散而兼瘀血内结。如坠马案“六脉散大，重取则弦小而长稍坚”（3852），散大为元气外散，弦小长为瘀血内结；治先补接，待散大渐敛再逐瘀（3853），说明元气虚散时纵有瘀血，亦当以固元气为先。"}, {"name": "主热盛津伤", "desc": "散大脉见于热病后期，主热盛津伤、气阴两耗。如太阴温病“脉浮大而芤……脉若散大者，急用之，倍人参”（24361），暑温“汗多脉散大，喘喝欲脱者，生脉散主之”（24380），皆因热邪迫津外泄，气阴耗散，脉失敛摄而散大。"}, {"name": "主正虚毒陷", "desc": "散大脉见于疮疡或久病，主气血两败、毒邪内陷。如骨槽风“脉左散大、右濡小”（18188），散大为气血涣散，濡小为气血衰微，症见舌㖞目定、阳缩、汗多，乃毒火蕴遏、伤阴耗气之陷症，预后不良。"}], "n": {"主气散阳脱": 11, "主气血耗伤": 3, "主中气虚寒": 2, "主元气虚散兼瘀": 3, "主热盛津伤": 1, "主正虚毒陷": 1}, "a": {"3692": "主气血耗伤", "3729": "主气血耗伤", "3852": "主元气虚散兼瘀", "3853": "主元气虚散兼瘀", "4290": "主元气虚散兼瘀", "12561": "主气散阳脱", "12562": "主气散阳脱", "12768": "主气散阳脱", "16072": "主气散阳脱", "16082": "主气散阳脱", "16105": "主气散阳脱", "16123": "主气散阳脱", "16226": "主气散阳脱", "16230": "主气散阳脱", "18188": "主正虚毒陷", "21653": "主气血耗伤", "24361": "主热盛津伤", "24380": "主气散阳脱", "24381": "主气散阳脱", "24641": "主中气虚寒", "24642": "主中气虚寒"}, "t": 21, "np": 0}, "pc:左+细+弱": {"o": "左脉细弱总属虚证，以气阴两虚、血虚阴亏为基础，进而累及脾肾阳气，致脾肾阳虚；阴血亏虚，水不涵木，则虚风内动；阴不制阳，则虚阳上浮；正虚之处，易受邪侵，痰瘀阻络，形成本虚标实之候。各类病机相互关联，总以正虚为本，或兼标实，反映了左脉细弱在虚损、风动、阳浮及痰瘀等病机中的广泛意义。", "c": [{"name": "主气阴两虚", "desc": "左脉细弱为气阴本亏之象，如段253言“气阴本亏，虚风内动”，段6443谓“弱为气血不足，细为阴血亏虚”，段8481称“左弱细为阴血不足”，皆因气血阴精亏耗，脉道不充，故见细弱。"}, {"name": "主脾肾阳虚", "desc": "左脉细弱可示脾肾阳气式微，如段269“阳陷入阴，命火式微”，段8481“脾肾两虚，自阴伤及阳”，段10509“脾气虚衰”，段24758“左脉细弱，肝肾气虚”，皆阳气不足，鼓动无力，脉道不充。"}, {"name": "主血虚阴亏", "desc": "细弱主阴血亏虚，如段10812“细弱主血虚”，段11928“产后营血亏虚”，段12296“肾水亏虚、阴不涵阳”，段19547“血虚阴亏”，段20392“真阴亏虚”，皆阴血不足，脉道不充。"}, {"name": "主虚风内动", "desc": "左脉细弱为气阴亏虚，虚风内动之基，如段253“虚风内动”，段11928“肝风上冒”，段18570“阴虚阳盛，卫气不得下行”，皆阴亏不能涵木，肝风内动，脉见细弱。"}, {"name": "主虚阳上浮", "desc": "左脉细弱可示阴虚阳浮、虚火上逆，如段8481“肾阳不藏，虚阳失守”，段10812“相火上逆”，段19547“胃气因热上逆”，段20392“虚阳外越”，皆阴不制阳，虚阳上浮。"}, {"name": "主痰瘀阻络", "desc": "左脉细弱主血虚，常与右脉弦滑并见，示本虚标实，如段253“痰浊上阻”，段10812“瘀血挟痰浊阻于肺胃之络”，段13684“瘀痰阻络、冲气上逆”，皆因虚致实，痰瘀阻络。"}, {"name": "阴虚火旺", "desc": "左脉细弱而见弦急，为阴血亏虚、木火上浮之象；多见于产后血去过多、津液大耗，虚火内炽，兼夹伏痰，属本虚标实之候。"}], "n": {"主气阴两虚": 2, "主脾肾阳虚": 3, "主血虚阴亏": 8, "主虚风内动": 1, "主虚阳上浮": 2, "主痰瘀阻络": 3, "阴虚火旺": 1}, "a": {"253": "主气阴两虚", "269": "主脾肾阳虚", "6443": "主血虚阴亏", "8481": "主虚阳上浮", "10509": "主脾肾阳虚", "10812": "主痰瘀阻络", "11928": "主虚风内动", "12296": "主血虚阴亏", "12297": "主血虚阴亏", "13573": "主血虚阴亏", "13684": "主痰瘀阻络", "14542": "阴虚火旺", "14663": "主血虚阴亏", "14815": "主痰瘀阻络", "18504": "主血虚阴亏", "18570": "主血虚阴亏", "19547": "主血虚阴亏", "20241": "主脾肾阳虚", "20392": "主虚阳上浮", "24758": "主气阴两虚"}, "t": 20, "np": 0}, "pc:左+和+平": {"o": "左·和平脉总起来主正气渐复、病势趋缓之候，但常兼见他部脉象异常，揭示余邪未清或潜在病机。其核心在于左脉平和而右脉或他部见动、数、弦、滑、实等，说明病位多在右部或中下焦，病机以阳升气火、余热未清、虚怯、胃气不和、冲气上逆、痰热内壅、肝虚火郁、肝热血逆等为主。各类之间相互关联：阳升气火与冲气上逆常因虚致逆，余热未清与痰热内壅多由热邪留恋，虚怯与肝虚火郁则示正气不足。左脉平和本身示肝血未伤、正气渐复，但需结合右脉及全身症候，判断病机之虚实寒热，不可仅凭左脉平和而忽视潜在病机。", "c": [{"name": "主阳升气火", "desc": "左脉平和而尺中微动，右关前动数，尺脉带数，为阳不潜伏、冲脉升动之象。烦心劳神、五志皆动，气机下潜时触阳气上升，冲脉升动，络血不宁，随咳呛上溢；行走喘促亦助气火。脉升动与咳呛失血同出一原，说明阳升气火、冲脉上逆为病。"}, {"name": "主余热未清", "desc": "左脉平和或圆活，右关尺数中带动，或右寸关些数而大，尺中少动。数主热，动主气机躁动，右关尺候中下焦，示中下焦仍有郁热扰动，气机未全宁静；右寸关数大示上中焦余热未清。整体为邪热渐退、气机向和之候，病势趋缓。"}, {"name": "主虚怯", "desc": "左脉渐有和平之象，但形貌怯弱、色白而嫩、脉亦不壮，为阳虚神怯显然。痰因惊起，惊后恶梦大汗，神气壮者不惊，此属阳虚神怯，不可因攻痰见效而忘其虚怯，当于化痰中微加益气。脉不壮正示虚怯本质。"}, {"name": "主胃气不和", "desc": "左部平和，右关弦大带滑。右关候阳明胃气，弦为气逆，大为气盛，滑主痰食。失血非虚损，乃阳明胃气不和，气逆扰动血络所致。胸脘不爽，正合胃气壅逆之症，只宜暂戒酒肉辛辣，胃和即愈。"}, {"name": "主冲气上逆", "desc": "左部平和微嫌无力，右部直上直下仿佛有力而按之非真有力。右部应冲脉，直上直下为冲气上逆之象，按之无力则非实。肾虚致冲气挟痰上冲，乱其神明，故胆怯、呃逆、癫狂唱呼；下焦觉凉、遗精，皆肾虚不固之候。"}, {"name": "主痰热内壅", "desc": "左脉近平和，右脉滑而实，舌黄苔满布，大便燥。数主热，滑实主痰热内壅。外感稽留肺胃，久而生炎欲腐，故咳嗽吐痰腥臭、羸弱。左脉近平和，病偏右部肺胃，脉象揭示热壅痰实之病机。"}, {"name": "主肝虚火郁", "desc": "右脉和平如常，左脉微弱，较差于右脉一倍。左候肝，微弱示肝木之气虚弱，不能条畅敷荣，所寄相火郁于左臂经络而作热，故左臂发热酸软。屡投凉剂伤脾胃，故消化力减。脉微弱与肝虚、臂热酸软相应。"}, {"name": "主肝热血逆", "desc": "左脉弦长，关脉犹弦而兼硬，右脉稍和平。弦长主肝胆气逆，硬为热灼筋急，数则热盛。肝胆之热上冲脑部，故头疼定时发作，午后加重、夜不能寐，心中觉热、饮食懒进，皆热扰之象。"}], "n": {"主阳升气火": 2, "主余热未清": 3, "主虚怯": 1, "主胃气不和": 3, "主冲气上逆": 1, "主痰热内壅": 2, "主肝虚火郁": 2, "主肝热血逆": 4}, "a": {"1007": "主阳升气火", "3077": "主余热未清", "3079": "主余热未清", "3083": "主余热未清", "4451": "主阳升气火", "5297": "主虚怯", "8516": "主胃气不和", "19527": "主冲气上逆", "19541": "主痰热内壅", "19795": "主肝虚火郁", "19808": "主肝热血逆", "20164": "主肝热血逆", "20272": "主肝热血逆", "20419": "主痰热内壅", "20505": "主肝热血逆", "20510": "主肝虚火郁", "20551": "主胃气不和", "20553": "主胃气不和"}, "t": 18, "np": 0}, "pc:寸+大+浮": {"o": "寸部浮大脉总以“阳浮气盛”为基本象义，但所主病机有虚实寒热之异。实者，或为气火上升、肝阳上扰，或为风热犯肺、热壅气分，或为热毒结胸、邪实壅盛，或为宿食内停、胃气不降，皆因浮大为阳、为热、为实，寸候上焦，故病多在上、在表、在气分。虚者，或为虚阳外浮、根本空虚，或为肺气伤损、卫外不固，或为津亏燥热、肺失清肃，皆因浮大无力、重按即无，为正气亏虚、阴不敛阳之候。各类之间，以“寸候上焦”为定位基础，以浮大之有力无力辨虚实：有力多主实热、气火、风热、结胸、宿食；无力多主虚阳、肺虚、津亏。临证须结合兼脉（如兼滞、兼涩、兼数、兼弦）及症状，方能准确判断病机归属。", "c": [{"name": "主气火上升", "desc": "寸脉浮大，浮为阳亢，大为气火有余。原文见“两寸脉浮大，气火上升，头眩，甚则欲呕吐”，乃厥阴肝阳化火上冲，胃气不降；又见“两寸浮大，关尺弦数”，为郁怒化火、气逆于上。故浮大之脉主上焦气火亢逆。"}, {"name": "主风热犯肺", "desc": "右寸候肺，浮主风热在表，大主热盛。原文见“右寸脉浮大”伴气急咳呛、痰多色黄，为风温化热壅肺；又见“风湿内并，脉滞寸口浮大”，苔微黄、脘闷头晕，为风湿郁而化热。故浮大主风热（或风湿化热）壅于肺卫气分。"}, {"name": "主虚阳外浮", "desc": "浮大而无力、重按即无，为正气亏虚、虚阳浮越之象。原文见“脉浮大不及于寸口”，伴腹大足肿，为脾肾两虚、水气不化；又见“右寸浮大，重按即无”，喘证无外感，为肺肾伤损、气不归元；又“上气喘急面肿肩息，脉浮大者死”，为虚阳上越。故浮大主虚阳外浮、根本空虚。"}, {"name": "主津亏燥热", "desc": "右寸浮大，浮为气分燥，大为津液亏。原文见“喉干失音，一月未复，津液不上供，肺失清肃，右寸脉浮大”，明言“气分燥津液亏”。故浮大主肺津亏耗、燥热内生，肺失清肃之病机。"}, {"name": "主热毒结胸", "desc": "寸口浮大，浮为阳热在上，大为热实内结。原文论结胸“寸脉浮，关脉沉”，又言“脉浮大者不可下，下之即死”，示热毒结聚心胸、气机壅塞，表邪未解而误下则逆。故浮大主热毒结胸、邪实壅盛。"}, {"name": "主宿食内停", "desc": "寸口浮大按之涩，为宿食阻滞、胃气不降。原文论宿食“寸口浮大按之涩，尺中微涩”，伴寒栗发热如疟、腹中痛不能食，皆宿食内停、邪实于中之征。故浮大（兼涩）主宿食不化、胃气壅滞。"}, {"name": "主肺气伤损", "desc": "右寸浮大而虚，为肺气伤损之候。原文“右寸浮大，肺气伤损”，与右寸脉细之肺气不足并列；又“右寸浮大无力为肺气虚”，伴自汗，为肺虚卫外不固。故浮大无力主肺气亏虚、腠理不固。"}], "n": {"主气火上升": 4, "主风热犯肺": 4, "主虚阳外浮": 1, "主津亏燥热": 1, "主热毒结胸": 2, "主宿食内停": 1, "主肺气伤损": 4}, "a": {"807": "主气火上升", "1044": "主津亏燥热", "3731": "主虚阳外浮", "4748": "主风热犯肺", "6598": "主风热犯肺", "17100": "主风热犯肺", "18419": "主肺气伤损", "18606": "主气火上升", "19361": "主气火上升", "19447": "主肺气伤损", "21555": "主宿食内停", "21803": "主气火上升", "21921": "主热毒结胸", "22970": "主热毒结胸", "24012": "主风热犯肺", "24710": "主肺气伤损", "24751": "主肺气伤损"}, "t": 17, "np": 0}, "pc:右+滑+沉": {"o": "右滑沉脉总以'痰、食、气、饮'内结于里为核心病机。沉主里、滑主痰主食，右脉候气分与脾胃，故其主病多归中焦脾胃与肺气壅滞。具体而言，滑沉应痰浊、饮邪、食积、气郁，四者常相兼为患；痰食气郁久可化热，故兼数则主热结；若兼虚象或弦硬浮等，则示瘀痰阻络或风火痰交织之虚实夹杂证。各段原文反复以'沉滑'为痰食内停之据，以兼脉定寒热虚实，故临床须结合兼脉与部位，辨痰、食、气、饮之孰重，以及是否化热、挟瘀、动风。", "c": [{"name": "主痰浊", "desc": "滑脉主痰，沉脉主里，右脉候气分与脾胃，故右滑沉脉多主痰浊内蕴。原文如'右关脉沉滑有力'示浊痰弥漫心窍，'右脉沉滑'主痰浊内阻，'右寸沉滑'主痰邪闭肺，皆以滑沉为痰浊内结之征。"}, {"name": "主食积", "desc": "右关候脾胃，沉主里滞，滑主宿食，故右关沉滑为食积内停之典型脉象。原文'右关沉滑，乃是食积'、'右脉沉滑，沉主里、滑主食积'，并据兼脉数、弦、紧分热积、寒积，明确沉滑为食积本脉。"}, {"name": "主气郁", "desc": "沉主气滞，滑主痰饮，右脉候气分，故右滑沉脉可主气机郁滞、气逆痰阻。原文'右脉沉滑，气逆痰阻'、'右关沉滑，气食相凝'，皆示气郁不展、升降失常，痰气交阻于中焦。"}, {"name": "主热结", "desc": "滑脉主痰，沉脉主里，痰郁日久可化热，或热与痰食相结。原文'右关沉滑有力'兼苔黄，示痰火内结；'或见滑数，内有热结'，滑数即沉滑兼数，为痰热或食积化热之象。"}, {"name": "主饮邪", "desc": "滑主痰饮，沉主里，右脉候脾胃，故右滑沉脉主饮邪内停。原文'右脉沉滑，内有痰饮'、'积痰积饮，作酸作呕'，皆以沉滑示饮停中焦、胃关不建，症见吐清水、呕食、嗳逆。"}, {"name": "主瘀痰阻络", "desc": "沉滑主痰浊内阻，若兼左脉细弱等虚象，则示瘀血挟痰浊阻络。原文'右脉沉滑，左脉细弱'，谓'瘀血挟痰浊阻于肺胃之络'，下焦相火随冲脉上逆，鼓动痰浊而呃逆，属虚实夹杂。"}, {"name": "主风火痰", "desc": "沉滑主痰，若兼弦硬浮等脉，则示痰浊内壅而风火鼓旋。原文'右关脉沉滑有力'，谓'浊痰弥漫，心窍闭阻'而'火风鼓旋之势尚炽'，症见口眼㖞斜、舌强言蹇，为痰火风交织之候。"}], "n": {"主痰浊": 2, "主食积": 6, "主气郁": 1, "主热结": 1, "主饮邪": 2, "主瘀痰阻络": 3, "主风火痰": 2}, "a": {"7236": "主风火痰", "10812": "主瘀痰阻络", "12452": "主痰浊", "12507": "主饮邪", "12511": "主饮邪", "12528": "主气郁", "13684": "主瘀痰阻络", "14061": "主热结", "14159": "主痰浊", "14815": "主瘀痰阻络", "15872": "主食积", "19322": "主食积", "19904": "主风火痰", "24629": "主食积", "24630": "主食积", "25029": "主食积", "25037": "主食积"}, "t": 17, "np": 0}, "c:小+缓": {"o": "小缓脉总属正气不足而邪气不盛之象。小为阳气或正气亏虚，缓为湿滞不运或邪热内伏而非实盛。其主病机可归为五类：正虚邪轻、阳运湿浊、湿胜热伏、虚热内伏、精滑虚损。诸类皆以虚为本，或兼湿、兼热、兼伏邪，然邪势均不鸱张，故脉不鼓击、不数大。正虚邪轻为总纲，余四类为具体病机之分化：阳运湿浊与湿胜热伏偏于湿，虚热内伏偏于热，精滑虚损偏于精亏。临床见小缓脉，多提示病势较缓、胃气尚存、邪未化燥成实，治宜扶正为主，或升阳除湿，或甘寒养阴，或清滋解泄，忌峻攻猛伐。", "c": [{"name": "主正虚邪轻", "desc": "脉小缓按之不鼓或鼓击无力，为正气不足而邪气不盛之象。如伏热客病，脉小缓不鼓，示非实热壅盛；肠澼脉小缓为易治，因胃气尚和、邪轻；热退脉小缓为邪退正安。总属虚人病轻、正虚邪微之候。"}, {"name": "主阳运湿浊", "desc": "形伟体丰而脉小缓，为阳气发泄、外似有余内实不足，水谷不得阳运，酿湿下注为浊病。小为阳气不足，缓为湿滞不运，故脉小缓主脾阳不运、湿浊下趋，治宜升阳。"}, {"name": "主湿胜热伏", "desc": "湿毒流注，脉缓而小，缓主湿、小主气血不足，断为湿胜于热、热伏湿中。湿得热而蔓延，循经窜络，脉不洪数而缓小，正合湿重于热、湿阻络脉之机。"}, {"name": "主虚热内伏", "desc": "积劳伤阳，伏热由募原流布三焦，脉来小缓，按之不数或微鼓，小为正气不足，缓为热邪内伏而非外感，且二便通、纳谷，无停积，故脉小缓主虚人伏热、邪未化燥成实。"}, {"name": "主精滑虚损", "desc": "精滑之症，脉以缓小为顺，缓小者正气尚能约束，虚而不甚；即见数象亦必无力，数而无力乃虚热扰动精室，非实火。若数而有力则火盛迫精，预后转恶，故缓小主虚损而精关尚固。"}], "n": {"主正虚邪轻": 4, "主阳运湿浊": 4, "主湿胜热伏": 2, "主虚热内伏": 5, "主精滑虚损": 1}, "a": {"554": "主虚热内伏", "767": "主正虚邪轻", "2902": "主正虚邪轻", "4366": "主虚热内伏", "4548": "主虚热内伏", "4930": "主虚热内伏", "5761": "主精滑虚损", "5778": "主阳运湿浊", "8652": "主阳运湿浊", "10635": "主阳运湿浊", "10879": "主湿胜热伏", "11256": "主虚热内伏", "14953": "主湿胜热伏", "17976": "主阳运湿浊", "18070": "主正虚邪轻", "23368": "主正虚邪轻"}, "t": 16, "np": 0}, "pc:左+微+弱": {"o": "左·微弱脉总属虚候，以正气不足、气血虚衰为共同基础。其主病机可归为五类：一主气虚，尤以胸中大气下陷为典型，脉多微弱而迟；二主阳虚，尺脉尤甚则下焦虚寒，脾肾阳衰；三主肝虚，左脉或左关微弱不起，肝气肝血虚弱，疏泄失职，相火郁于经络；四主正虚邪恋，脉虽微弱而根柢尚存，或左弱右实并见，示虚中夹实、虚实错杂；五主脏虚，为五脏正气内衰之总象。各类之间以“虚”为纲，气虚、阳虚、肝虚、脏虚皆属正气亏虚，惟病位与兼邪不同；正虚邪恋则虚中夹实，为虚候之变。故临证见微弱脉，首辨虚之所在，次察有无兼邪，不可一概而论。", "c": [{"name": "主气虚", "desc": "微弱脉为气虚之征，尤以胸中大气下陷为典型。原文见左右皆微弱、至数稍迟，断为气虚阳运无力，大气不达脑中则神昏，不潮舌本则舌干，不布营卫则身凉，脉微弱迟正合此机。"}, {"name": "主阳虚", "desc": "微弱主阳气衰微，尺脉尤甚则病在下焦。原文见溏泻不止、带红色、怔忡不食，脉左右皆微弱而尺尤甚，断为下焦虚寒、脾肾阳虚，温补下焦而效。"}, {"name": "主肝虚", "desc": "左脉微弱不起，左关独微弱，皆主肝气肝血虚弱。肝虚不能疏泄条畅，相火郁于经络则臂热腿疼，温煦不足则心中寒凉、饮食减少，肝络失养则胁下作疼，治以补肝养血而愈。"}, {"name": "主正虚邪恋", "desc": "脉左右皆微弱而根柢尚存，或左弱右实并见，示正气虽虚而邪未净。如食结肠中呕吐便秘，脉微弱至数照常，知胃气未绝犹可救；久泻左脉微弱右部颇实，为正虚兼肠胃积热，属虚实错杂。"}, {"name": "主脏虚", "desc": "华元化论五脏之虚，诊其脉举指而滑、按之而微，又谓按之沉小微弱短涩软濡俱为脏虚。微弱为正气内衰之象，故主五脏虚损，见肠鸣气走、足冷手寒、食不入胃、精神不收等症。"}], "n": {"主气虚": 4, "主阳虚": 1, "主肝虚": 5, "主正虚邪恋": 1, "主脏虚": 1}, "a": {"19492": "主气虚", "19496": "主气虚", "19621": "主阳虚", "19794": "主肝虚", "19795": "主肝虚", "19870": "主气虚", "19874": "主肝虚", "19884": "主肝虚", "19955": "主肝虚", "20501": "主气虚", "20663": "主正虚邪恋", "22693": "主脏虚"}, "t": 12, "np": 0}, "c:滑+弱": {"o": "弱滑脉总以弱示正气不足、滑示痰湿内阻为基本病机，其核心在于胃气尚存与痰湿内扰并存。弱而滑，脉道柔和流利，是胃气未败之象，故原文屡言“脉弱以滑，是有胃气，命曰易治”，预后较佳。然弱滑亦主具体病证：滑主痰，弱主虚，合见则痰湿内阻而正气已伤，可见脾阳虚弱、痰湿内阻；弱主气血不足、脾阳虚弱、肝肾两虚，故主虚损；浮滑偏于痰热壅肺，见咳痰脓血；两关滑而尺弱，则为肝肾两虚、虚风煽络、痰随风动。诸类之间，胃气存为总纲，虚损与痰湿为病理基础，痰热壅肺与内风痰阻为具体病位之变，总不离正虚邪滞、痰湿为患。", "c": [{"name": "主胃气存", "desc": "脉弱以滑，柔和流利，为胃气尚存之象。原文屡言“脉弱以滑，是有胃气，命曰易治”，强调弱而不失滑利，则脉道柔和，元气未败，病虽重而可治；反之脉实以坚则失胃气。"}, {"name": "主虚损", "desc": "弱脉主气血不足、脾阳虚弱、肝肾两虚。原文“右脉稍弱而滑”为气血不足；“脉弱舌滑”为脾阳与胃阴两伤；“尺弱”为肝肾两虚。弱象示正气亏虚，滑象示虚中夹痰或虚风内动。"}, {"name": "主痰热壅肺", "desc": "左脉浮滑，浮主热，滑主痰，合为痰热壅肺之象。原文见咳甚痰脓带血，断为妊兼肺痈，以左脉浮滑验之；浮滑示肺中痰热壅盛，故用清肺泻肺之剂取效。"}, {"name": "主内风痰阻", "desc": "两关滑而尺弱，滑主内风痰阻，尺弱主肝肾两虚。原文谓“肝肾两虚，虚风煽络”，症见舌强肢麻、口眼㖞斜、溲多筋酸，滑为痰，弱为虚，痰随风动，络脉失养。"}], "n": {"主胃气存": 7, "主虚损": 1, "主痰热壅肺": 2, "主内风痰阻": 1}, "a": {"4115": "主痰热壅肺", "10461": "主虚损", "11648": "主内风痰阻", "15178": "主痰热壅肺", "21819": "主胃气存", "22745": "主胃气存", "22764": "主胃气存", "22803": "主胃气存", "23233": "主胃气存", "23242": "主胃气存", "23703": "主胃气存"}, "t": 11, "np": 0}, "c:浮+芤": {"o": "浮芤脉总以浮为阳热或气浮，芤为阴血津液亏伤为基本病机，二者相合，多示热盛伤津、血络受损或阴虚阳浮之候。所主病机可归为五类：津亏血伤、热盛胃实、肺络损伤、痧毒犯经、阴虚阳浮。其中津亏血伤是核心，贯穿诸段；热盛胃实侧重阳热与阴伤相搏，胃燥津竭；肺络损伤与痧毒犯经均以芤主血伤、浮主病位在表在上为据，示血络受损或痧毒犯经；阴虚阳浮则强调阴不配阳、阳气外浮。各类之间以“阳热—阴伤”为共同纽带，或偏于热盛，或偏于血伤，或偏于阳浮，总不离浮芤相搏、阴阳不相维系之机。", "c": [{"name": "主津亏血伤", "desc": "浮芤并见，浮为阳热，芤为中空，示阴血津液亏耗、脉道不充。如温病自汗、神昏谵语，热盛伤津；趺阳脉浮芤，荣气伤而宗气衰，身体瘦、肌肉甲错；产后转脬，血虚失守。皆以芤主血伤津亏为据。"}, {"name": "主热盛胃实", "desc": "浮主阳热有余，芤主阴血不足，浮芤相搏则胃气生热，其阳则绝。原文屡言“浮芤相搏，胃气生热”，或右手关上阳实，肠中伏伏不思食，得食不能消，示胃实热结、阴液耗竭之病机。"}, {"name": "主肺络损伤", "desc": "浮主风温袭肺、病位在表在上，芤主络损血溢、阴血外泄。原文风温袭肺，由咳而致见红，时来时止，脉象浮芤，虑其复涌，正示风热在肺而血络已伤，故主肺络受损、血外溢之病机。"}, {"name": "主痧毒犯经", "desc": "原文以脉辨痧在何经：脉芤而浮者手太阴肺痧，芤而数者手少阴心痧，芤大滑实者足太阴脾痧。芤主血伤，浮数等各应脏腑，故浮芤相合示痧毒犯肺、血络受伤，为痧邪所犯之经的病机。"}, {"name": "主阴虚阳浮", "desc": "浮为阳气外浮，芤为阴血不足，浮芤并见且不任重按，示阴虚阳亢、热扰心神。原文左脉浮弦硬、右脉浮芤，症见昏睡、发热、怔忡、便闭溺少，乃阴血亏虚、阳气外浮、虚热内扰之候。"}], "n": {"主津亏血伤": 2, "主热盛胃实": 5, "主肺络损伤": 1, "主痧毒犯经": 1, "主阴虚阳浮": 1}, "a": {"5137": "主热盛胃实", "7547": "主肺络损伤", "18267": "主热盛胃实", "18443": "主痧毒犯经", "18795": "主津亏血伤", "18942": "主热盛胃实", "20383": "主阴虚阳浮", "20880": "主热盛胃实", "21581": "主热盛胃实", "27100": "主津亏血伤"}, "t": 10, "np": 0}, "pe:尺+浮": {"o": "尺·浮脉总以“下焦阴气不藏、虚阳外浮”为纲，然所主病机有虚实寒热之殊。其虚者，或肾水亏乏、真阳不潜，见足跟痛、气短、噎膈；或阴亏火旺，迫血上溢而衄血；甚则阴竭阳浮、阴阳离决，现循衣摸床、谵语等危候。其实者，或客阳在下焦、肾与膀胱热而小便难；或湿热郁蒸成沙淋；或风寒相搏、伤肾发黄成谷疸；或表邪弥漫，尺寸俱浮而头身痛。诸类之间，总由尺部当沉反浮，失其封藏之职：虚证为阴不敛阳，实证为邪热扰于下焦，表证为邪气弥漫及尺，危证为阴阳不相接续。故同一尺浮，须参有无根、兼脉兼症，以辨虚实吉凶。", "c": [{"name": "主肾虚阳浮", "desc": "尺脉当沉反浮，为肾水亏乏、真阳不能潜藏而外浮。原文见“尺脉浮而无根”“尺浮下焦阴气不藏”，多伴足跟痛、气短、目睛晕黄等，甚则虚损、噎膈。浮大无力或兼涩，非实热，乃阴不敛阳之象。"}, {"name": "主下焦客热", "desc": "尺脉浮为客阳在下焦，或肾与膀胱热、水气涩滞。原文“尺脉浮者，客阳在下焦”“尺脉浮，小便难”，因热势微而水行不利，故小便难而有余涩；亦见沙淋湿热郁蒸，按之弦数，阴分已伤。"}, {"name": "主伤肾发黄", "desc": "尺脉浮为伤肾，与趺阳脉紧同见，主风寒相搏、谷气不消、浊气下流、热流膀胱，身体尽黄，名曰谷疸。原文反复言“尺脉浮为伤肾，趺阳脉紧为伤脾”，示肾伤而脾亦困，湿热瘀郁发黄。"}, {"name": "主血虚火旺", "desc": "左尺脉浮主肝肾阴虚、虚火上炎，火迫血溢而衄血；阳脉浮、阴脉弱则血虚，血虚筋急。原文“左尺脉浮，肝肾阴虚”“阳脉浮、阴脉弱者，则血虚”，皆以尺浮为阴亏不藏、虚火妄动之征。"}, {"name": "主表邪弥漫", "desc": "尺寸俱浮，主寒邪外袭、表气皆浮，见头身俱痛、翕翕发热、啬啬振寒。原文“脉体尺寸俱浮，证势头身俱痛”，虽尺部亦浮，乃表邪弥漫、卫阳被郁，非独下焦病，治当祛邪返正、得汗便解。"}, {"name": "主阴阳离决", "desc": "尺脉浮而无根，或两尺按之即无，为肾阴将竭、真元不固，阳升而阴不能应。原文见“两尺按之即无”“尺脉浮而无根”，伴目清白无见、循衣摸床、谵语，属正虚邪盛、阴阳不相接续之危候。"}], "n": {"主肾虚阳浮": 6, "主下焦客热": 3, "主伤肾发黄": 4, "主血虚火旺": 7, "主表邪弥漫": 2, "主阴阳离决": 4}, "a": {"940": "主肾虚阳浮", "3511": "主血虚火旺", "3680": "主肾虚阳浮", "3681": "主肾虚阳浮", "4439": "主肾虚阳浮", "8312": "主阴阳离决", "9041": "主下焦客热", "12371": "主表邪弥漫", "15294": "主肾虚阳浮", "18724": "主血虚火旺", "19693": "主阴阳离决", "20703": "主阴阳离决", "21297": "主肾虚阳浮", "21416": "主伤肾发黄", "21807": "主下焦客热", "21811": "主阴阳离决", "22232": "主下焦客热", "22760": "主表邪弥漫", "22837": "主血虚火旺", "22934": "主血虚火旺", "23582": "主伤肾发黄", "24738": "主血虚火旺", "24739": "主血虚火旺", "25386": "主伤肾发黄", "25387": "主伤肾发黄", "25998": "主血虚火旺"}, "t": 26, "np": 0}, "pe:左+洪": {"o": "左洪脉总属阳热亢盛之象，主实证、热证，但须辨虚实。洪而有力，多主实热炽盛，可因部位不同而分脏腑气血：左洪主血分热盛，右洪主气分热盛，见于温病、阳明热盛、肝火、肺火等。洪而无力或洪数失和缓，则主虚火，如阴亏火旺、虚阳浮越、气血虚而热壅。洪兼滑主痰热，洪兼数主热盛，洪兼弦主肝火。洪脉亦可见于邪实证虚、虚中夹实之候，如洪而不任重按。各类之间以热盛为核心，实热与虚火为两大纲，痰热、血热、邪实证虚为兼夹变证。", "c": [{"name": "主热盛", "desc": "洪脉为阳热亢盛之象，气血涌盛，脉道充盈。原文如'左脉洪而有力'主温邪陷入下焦血分；'右脉洪而有力'主阳明热盛；'右寸脉洪'主肺家火旺。洪而有力者，多属实热炽盛，随部位不同而分脏腑气血。"}, {"name": "主虚火", "desc": "洪而无力或洪数失和缓，为虚阳浮越、阴亏火旺之征。如老人内伤胃虚，脉洪数左甚，断为虚阳浮越；产后血虚，左脉略洪而驶，为血分伏热；右脉洪而无力，为气血虚而热壅于外。洪大而虚，多主阴精亏虚、龙雷之火上亢。"}, {"name": "主痰热", "desc": "洪兼滑象，为痰火交结、实热内蕴。原文如'脉左右皆弦、右部弦而有力'，虽非典型洪脉，但结合总述，滑洪脉主痰热壅盛，病位可在肺胃、肝胆、阳明腑，症见呕血、胸胀、便结、胁痛等。洪为火盛，滑为痰聚，合主痰热实证。"}, {"name": "主血热", "desc": "左脉洪而快或洪而有力，主血分有热、热迫血妄行。如产后经行不止，左脉略洪而快，断为血热妄行，治以凉血；温邪陷入下焦血分，左脉洪而有力。左候血分，洪为热盛，故主血热。"}, {"name": "主邪实证虚", "desc": "洪而不任重按，或与弱脉并见，为邪热盛而正气已虚。如温病半月，右脉近洪而不任重按，断为'邪实证虚'；脚气壅疾，右脉洪而无力，左脉伏，为虚中夹实、壅滞不通。洪而无力，示热壅于外而气血内虚。"}], "n": {"主热盛": 2, "主虚火": 2, "主痰热": 1, "主血热": 4, "主邪实证虚": 3}, "a": {"3332": "主邪实证虚", "4010": "主血热", "5159": "主血热", "8446": "主邪实证虚", "12716": "主虚火", "15083": "主虚火", "15188": "主血热", "20123": "主热盛", "20228": "主痰热", "20349": "主邪实证虚", "20681": "主热盛", "24738": "主血热"}, "t": 12, "np": 0}, "pe:尺+细": {"o": "尺部细脉总以虚为纲，细主脉道不充、阴血阳气不足，尺候肾与下焦，故所主病机多归肾虚、阴亏、阳衰、气虚诸类。其轻者见肾虚不固、阴液亏虚、阳虚内寒、气虚不运，皆本虚之候；其重者则阴竭阳衰，正虚邪陷，或气机阻绝，上下不通，症脉相反。各段原文或言“肾病何辞”，或言“下焦冷无阳气”，或言“阴液欲尽”，或言“膀胱气弱”，皆从尺细推出下元虚损、根本失守之机。其间兼见数、沉、弱、垂等象，则虚中夹火、夹寒、夹痰、夹滞，然总不离尺部细脉主下焦虚损、阴阳气血不充之总纲。", "c": [{"name": "主肾虚不固", "desc": "尺脉候肾，细为阴弱，尺垂或细如丝则下元不固、肾失摄纳。原文见脉细尺垂、形瘦食少、动则气促喘急，明言“肾病何辞”，治以收摄固真；又有右尺细如丝为下焦气弱，故主肾虚不固、纳气无权。"}, {"name": "主阴液亏虚", "desc": "细脉主阴血不足，尺部细而无力或尺不附骨，则肾阴耗竭、根本失守。原文见鼻煤龈血、舌张干涸、肌如甲错、脉细尺不附骨，示阴液欲尽、邪热内迫，有油干焰灭之危，故主阴液亏虚。"}, {"name": "主阳虚内寒", "desc": "尺脉细而弱或细微，阳气衰微，下焦冷无阳气。原文谓尺脉弱者下焦冷、无阳气，上热冲头面；尺脉细微则溏泄冷利，尺脉虚小则足胫寒、痿痹脚疼，皆阳气不能温煦所致，故主阳虚内寒。"}, {"name": "主气虚不运", "desc": "细弱之脉示脉道不充、气血不足，尺部细弱则下焦气弱，推动无力。原文见六脉微弱、右关尤甚、右尺细如丝，断为脾虚不运之便秘；又右尺脉细主膀胱气弱，左寸脉细主小肠气弱，故主气虚不运。"}, {"name": "主正虚邪陷", "desc": "温病、伤寒或疟痢过程中，脉细小难得或尺细不附骨，为正虚不能抗邪、邪气内陷之征。原文谓温病脉细小者死，疟变为痢、阴液欲竭、脉细尺不附骨，示正不胜邪、根本失守，故主正虚邪陷之危候。"}, {"name": "主气机阻绝", "desc": "尺脉细甚至无脉，而症见胸腹大痛、昏倒、手足逆冷、两手握固，非真脱乃伤食痞塞、阴阳不通、上下阻绝。原文引“上部有脉，下部无脉，其人当吐不吐者死”，断为气机阻绝，尺细非绝脉，故主气机阻绝。"}], "n": {"主肾虚不固": 2, "主阴液亏虚": 2, "主阳虚内寒": 1, "主气虚不运": 3, "主正虚邪陷": 1, "主气机阻绝": 1}, "a": {"1257": "主肾虚不固", "4466": "主肾虚不固", "8380": "主气机阻绝", "8573": "主阴液亏虚", "15942": "主阴液亏虚", "17233": "主气虚不运", "21807": "主阳虚内寒", "21824": "主正虚邪陷", "22760": "主气虚不运", "25096": "主气虚不运"}, "t": 10, "np": 0}, "pe:尺+微": {"o": "尺·微脉总主阳气衰微、阴寒内盛之病机。其核心为下焦阳虚，故见尺部脉微；阳虚则阴寒内生，或虚阳上浮，或冲气上逆，或神气浮散，或气血俱虚。各段所论，或单见尺微，或寸口与尺并见，皆不离阳衰阴盛之本质。微为阳衰，弱为阴不足，濇为血少，伏为火不归元，诸脉相兼，则病机有偏重：兼紧者阴寒凝滞，兼沉者饮停气逆，兼豁大无力者气血两虚，兼寸盛者神气浮散。要之，尺微脉以肾阳亏虚为根，或致虚火游走，或致冲逆，或致神散，或致下寒，总属虚损之候，治宜温阳益气、引火归元、平冲降逆，忌汗下攻伐。", "c": [{"name": "主阳虚阴盛", "desc": "尺脉微而寸口亦微或沉，为阳气衰微、阴寒内盛。原文如“寸口脉微，尺脉紧，其人虚损多汗，知阴常在，绝不见阳也”，又“少阴病，脉微，不可发汗，亡阳故也”，皆示阳衰阴凝、阴阳离决之机。"}, {"name": "主肾虚火浮", "desc": "尺脉微而伏，或微无力，主肾虚阳衰、虚火不归元。原文“右尺脉伏而不起……尺脉沉伏者，肾虚也；日夜之热上下循环者，肾火之浮游也”，又“两尺脉微如丝……虚阳上浮”，皆肾虚火浮之候。"}, {"name": "主气血两虚", "desc": "尺脉微而弱濇，或六部豁大无力，主气血俱虚。原文“尺脉弱濇者……下焦阴阳俱虚”，又“六部俱豁大，浮中沉无力……脱血益气正宜”，皆示气血亏虚、荣卫不足之病机。"}, {"name": "主冲气上逆", "desc": "尺脉微而寸沉，主下焦阳虚、冲气挟饮上逆。原文“寸脉沉，尺脉微，手足厥逆，气从小腹上冲胸咽……与桂苓五味甘草汤”，又“尺微为下焦阳弱……沉紧为水寒相搏”，皆阳虚饮逆、冲气上冲之机。"}, {"name": "主神气浮散", "desc": "尺脉微而寸盛，前大后小，按之忽无举之忽有，主根本动摇、神气浮散。原文“脉来寸盛尺微、前大后小、按之忽无举之忽有，为神气浮散之候”，又“两寸与左关洪大而散，为虚阳上浮、元气涣散”，皆精气下脱、神气不守之危候。"}, {"name": "主下焦虚寒", "desc": "尺脉微细或弱，主下焦阳虚、寒湿内盛。原文“尺脉细微，溏泄冷利”，又“尺脉弱，下焦冷，无阳气”，又“右关尺脉微续、细、弦……阴寒未散、阳未全回”，皆下焦虚寒、阳气不足之病机。"}], "n": {"主阳虚阴盛": 8, "主肾虚火浮": 2, "主气血两虚": 4, "主冲气上逆": 5, "主神气浮散": 2, "主下焦虚寒": 1}, "a": {"3511": "主气血两虚", "3606": "主肾虚火浮", "3775": "主神气浮散", "4228": "主肾虚火浮", "11587": "主阳虚阴盛", "18339": "主阳虚阴盛", "18724": "主阳虚阴盛", "18801": "主阳虚阴盛", "18963": "主阳虚阴盛", "21654": "主冲气上逆", "21807": "主下焦虚寒", "21824": "主神气浮散", "22033": "主冲气上逆", "22837": "主阳虚阴盛", "22858": "主阳虚阴盛", "22891": "主气血两虚", "22925": "主阳虚阴盛", "22934": "主气血两虚", "23970": "主气血两虚", "25347": "主冲气上逆", "25348": "主冲气上逆", "25777": "主冲气上逆"}, "t": 22, "np": 0}, "pe:六+平": {"o": "六·平脉总起来主邪退正复、胃气未败、脏复阳潜及体质时令之常，亦可见于孕脉与郁火痰气之轻证。其核心在于脉来和缓流利、无病脉之象，示胃气犹存、正气渐复，故以脉平为邪退之验，以脉平辨胃气未败，以无病脉即平脉主脏复阳潜。然脉平非病愈，余邪未化、脉虽平而瘕胀痹痛未除，故须脉证合参。孕脉独右尺洪大有力，郁火痰气独关部滑促弦芤，皆以六脉平为背景而显病机。体质时令之平脉则示脉随人变、应时和缓，不可执一。诸类之间，以胃气为本，和缓为要，平中察独，方得平脉之真。", "c": [{"name": "主邪退向愈", "desc": "脉由病脉转为平和流利，或六脉稍平、匀平，示余邪大势已减、正气渐复。如六脉稍平、六部平静而流利、二帖脉平，皆邪退正安之象，然余邪未尽，恐有反复。"}, {"name": "主胃气未败", "desc": "六脉虽平而形色不变、起居如常，或冲阳脉尚平，示胃气犹存。如长期不食而六脉匀平，六脉洪大而冲阳尚平，皆胃气未败，预后可治，非脾胃虚衰之候。"}, {"name": "主脏复阳潜", "desc": "六脉虽未调和，然无病脉之象，如左关弦退、右关鼓指而寸尺软弱虚细，示肝阳潜伏、脏阴渐复，古人所谓“未见病脉，即平脉也”，主向愈之机。"}, {"name": "主孕脉", "desc": "六脉皆平而独右尺洪大有力，为孕脉特征。如妇人年四十余得孕，六脉皆平，惟右尺洪大有力，兼择食，断为孕无疑，示孕则气血充盛、胞宫脉旺。"}, {"name": "主郁火痰气", "desc": "六脉虽平而独左关带滑，或气口数盛而促、人迎弦大而芤，示肝郁化火、痰气中结。如左关滑主肝气不舒、郁而生火；数盛促主痰热，弦大芤主惊怒伤肝、阴血亏虚。"}, {"name": "主时脉胃脉", "desc": "六部中俱带弦洪浮沉为时脉，中按和缓为胃脉，脏腑胃脉既平又应时脉乃无病。如春弦夏洪秋浮冬沉，关键在是否有和缓胃气，反此则病，示平脉须合时脉与胃气。"}], "n": {"主邪退向愈": 7, "主胃气未败": 3, "主脏复阳潜": 1, "主孕脉": 1, "主郁火痰气": 2, "主时脉胃脉": 1}, "a": {"2000": "主邪退向愈", "2097": "主脏复阳潜", "2923": "主邪退向愈", "3458": "主胃气未败", "3658": "主邪退向愈", "3661": "主郁火痰气", "4184": "主胃气未败", "5341": "主邪退向愈", "5450": "主邪退向愈", "15508": "主胃气未败", "17250": "主邪退向愈", "17301": "主郁火痰气", "17459": "__np", "19143": "主孕脉", "19666": "主邪退向愈", "22867": "主时脉胃脉"}, "t": 16, "np": 1}, "pc:左+数+滑+大+小+濡": {"o": "左·数滑大小濡脉总起来主热、痰、邪实与津亏。数主热，滑主痰，大主邪实，右部搏指为肺胃热炽；左部小濡为津亏之象。诸脉象并见，反映痰热蕴结、邪实壅盛而兼津液耗伤之病机。热与痰搏，火与痰激，故痰鸣有声；热灼津亏，故渴饮频作。邪实与津亏并存，提示病机复杂，实中夹虚。各脉类之间相互关联：热为痰之因，痰为热之果；邪实与津亏并见，乃热盛伤津之必然。总以痰热邪实为主，津亏为兼，治疗当泻肺开痰、导热下行，兼顾护津。", "c": [{"name": "主热", "desc": "脉数主热，原文明言“数主热”，且见舌质转红、边尖绛意、神烦、频渴欲饮、两颧红赤等症，皆热邪内盛之象。热势仍不见衰，说明邪热炽盛，故数脉为热病之征。"}], "n": {"主热": 1}, "a": {"7317": "主热"}, "t": 1, "np": 0}, "c:细+沉+浮+小+紧": {"o": "浮细小沉紧脉在此段总起来主邪结于里、气机壅塞之病机，具体分三类：一为热毒结聚心胸之结胸，脉见寸浮关沉，属热实内结；二为表邪未解，脉浮而大，误下则逆；三为阴寒凝结之脏结，脉见关上细小沉紧，属阳虚寒结。三类虽寒热虚实不同，但共同反映邪气结聚、气机不通之本质。浮脉主邪在表或热邪上炎，沉紧主邪结于里、寒凝气滞，细小主阳微或正虚。结胸为热结，脏结为寒结，表邪未解为邪在表，三者以脉位、脉形及兼脉区分寒热虚实，体现了同一脉象组合在不同病位与病性下的辨证意义。", "c": [{"name": "主热毒结胸", "desc": "原文'病发于阳而早下之，热气乘虚而痞结不散'，寸口浮关上沉，为热毒结聚心胸、气机壅塞之象，按之痛而成结胸。脉浮主热邪上炎，沉主热结于里，故浮沉并见主热毒内结之实证。"}], "n": {"主热毒结胸": 1}, "a": {"21921": "主热毒结胸"}, "t": 1, "np": 0}, "c:数+弦+沉+涩": {"o": "涩沉弦数脉总起来主气郁血滞、伏热内蕴，兼见血虚风动、湿痰、金水两虚等复杂病机。其核心在于'郁'与'滞'：沉弦主气郁，涩主血滞，数主伏热，三者相合，多因情志抑郁致气机不宣，暑邪内伏，血为邪踞而不流行，故见胁腹梗塞、凛寒发热等症。若兼见涩数不调，则示血虚肝风暗动；右关缓滑，则兼胃有湿痰；尺寸俱弱，则兼金水两虚。诸类之间，气郁为始动因素，血滞为郁之深化，伏热为郁滞所化，而血虚风动、湿痰、金水两虚则为兼挟之虚损或病理产物。临证当以清气宣郁为先，气机宣通则热露瘀行，不可早投血药引邪深入。", "c": [{"name": "主伏热", "desc": "数脉主热，原文谓'数主伏热'或'数主热'。暑邪内伏，郁而化热，热未外露，故舌无苔、口不渴、便溺如常，而脉数。此热因气郁而伏于内，非表热也。"}, {"name": "主血虚风动", "desc": "涩数为血虚，沉弦属肝，数而不调为风动之征。原文断'血虚而肝风暗动'，症见耳聋、肩膊酸而难举，皆血虚不能荣养筋脉，肝风内动之象。"}], "n": {"主伏热": 3, "主血虚风动": 2}, "a": {"13114": "主伏热", "13590": "主血虚风动", "14034": "主伏热", "14330": "主伏热", "14695": "主血虚风动"}, "t": 5, "np": 0}, "c:弦+大+浮+短": {"o": "弦浮大短脉总属邪实壅盛、三阳合病之象。弦主少阳枢机不利，浮主邪郁肌表，大主阳明热盛，短气为气机壅滞之征。其病机核心为外邪侵袭、表里俱病，进而湿热郁蒸、气机壅滞。三类病机相互关联：少阳阳明合病为始，湿热郁蒸发黄为进展，气机壅滞贯穿始终。脉象未大坏者，提示正气尚存，故可治；若脉续浮，则邪仍偏表，可与小柴胡汤和解。总之，此脉主邪实壅盛、三阳合病，以少阳阳明为重心，兼夹湿热与气滞。", "c": [{"name": "主少阳阳明合病", "desc": "脉弦浮大，弦主少阳，浮主表，大主阳明热盛。原文见'阳明中风''三阳合病'，症见寒热频作、鼻干不得汗、嗜卧、耳前后肿等，为风邪外袭、少阳枢机不利、阳明热盛之表里俱病。"}, {"name": "主湿热郁蒸发黄", "desc": "脉弦浮大而短气，伴一身及目悉黄、小便难、腹都满、潮热、时时哕。湿热郁蒸脾胃，气机壅滞，胆液外溢，故见黄疸；脉大主热盛，浮主邪郁肌表，弦主枢机不利。"}], "n": {"主少阳阳明合病": 2, "主湿热郁蒸发黄": 1}, "a": {"3356": "主少阳阳明合病", "18936": "主少阳阳明合病", "25978": "主湿热郁蒸发黄"}, "t": 3, "np": 0}, "c:弦+浮+虚+洪": {"o": "浮洪弦虚脉总属大虚之候，以虚为根本。浮洪为虚阳外越，非实热；弦为气逆，因虚而气机上逆；虚为不足，血气已衰。三者相合，常见于年高劳伤、酒伤气血、胃气衰败之噎膈反胃等症。其病机核心是虚，虚阳外越、气逆、瘀血夹虚皆由虚所致。原文强调此脉非热非痰，误用凉药则助阴伤阳，误用香燥则耗气伤胃，治当补虚敛脉。故浮洪弦虚脉主大虚，兼见虚阳外越、气逆、瘀血夹虚等，总以补虚为要。", "c": [{"name": "主大虚", "desc": "脉浮洪弦虚，浮洪为虚阳外越，弦为气逆，虚为不足，总属大虚之症。原文强调年逾六十，过劳好酒，血气已衰，脉见浮洪弦虚，本为大虚，非热非痰，治当补虚敛脉。"}, {"name": "主瘀血夹虚", "desc": "脉涩不匀，重取大而无力，及浮洪弦虚，皆瘀血夹虚之候。原文治噎膈反胃，以韭汁等润养行瘀而效，说明瘀血内阻兼虚，脉见浮洪弦虚，不可纯攻。"}], "n": {"主大虚": 2, "主瘀血夹虚": 1}, "a": {"3679": "主瘀血夹虚", "15118": "主大虚", "15119": "主大虚"}, "t": 3, "np": 0}, "pc:左+数+弦+小+动": {"o": "左数弦小动脉总属阴虚阳亢、内风旋动之候。其脉小为阴血不足，弦动为风阳上扰，数为热象，四类病机相互关联：阴虚为本，热为标，热耗津液则阴更虚；阴虚不制阳，则阳亢化风，风阳升于上而见头晕、目泪、舌刺，下焦无气而见足痿。故本脉以虚为本，以热、风、阳亢为标，标本相兼，总归肝肾阴亏、内风旋动、虚热上扰之机。", "c": [{"name": "主阴虚", "desc": "脉小为阴血不足之象，左脉候肝肾，小弦并见，示肝肾阴亏。原文谓“虚则内风再旋”，右脉略虚亦佐证阴分亏虚，故主阴虚。"}], "n": {"主阴虚": 2}, "a": {"784": "主阴虚", "4408": "主阴虚"}, "t": 2, "np": 0}, "pc:右+数+弦+沉+涩": {"o": "此脉总起来主血虚风动、湿痰内蕴与金水两虚三类病机。左手脉沉弦而涩数不调，突出肝血亏虚、虚风暗动；右关独缓滑，专主胃中湿痰；尺寸俱弱，则示肺肾两虚。三者虽分属不同脉位与脏腑，但相互关联：血虚风动可影响津液输布而生痰，湿痰中阻又可耗伤肺肾，金水两虚则加重肝血不足与风动之势。合而观之，此脉反映本虚标实、多脏同病之复杂病机，以血虚风动为主导，湿痰与金水两虚为兼夹，临证需权衡主次。", "c": [{"name": "主血虚风动", "desc": "原文以左手脉沉弦而涩数不调为据，沉弦属肝郁，涩为血少，数而不调乃风动之征，故断为血虚而肝风暗动。此脉象组合反映肝血亏虚、筋脉失养，虚风内动之病机。"}], "n": {"主血虚风动": 2}, "a": {"13590": "主血虚风动", "14695": "主血虚风动"}, "t": 2, "np": 0}, "c:数+浮+小+缓": {"o": "浮缓小数脉总起来主风火相搏、表热内蕴兼正气不足之病机。浮为风，数为火，缓小示风火相搏而正气不足，故其病机核心为风火为患，或上攻头面清窍，或外袭肌表而兼里热。两类病机相互关联：风火在表可循经上攻，形成头胀、齿痛、耳聋等症；而缓小之象又提示正气不足，抗邪无力，故病虽在表而‘非轻候’。临床见此脉，当辨风火之轻重与正虚之程度，治宜疏风清火，兼顾护正，不可纯用苦寒攻伐。", "c": [{"name": "主风火", "desc": "脉浮缓小数，浮为风，数为火，缓小示风火相搏。原文见齿痛头胀、耳聋鸣、咽嗌不爽，皆风火循经上攻头面清窍所致，故主风火上攻之病机。"}], "n": {"主风火": 2}, "a": {"15519": "主风火", "15755": "主风火"}, "t": 2, "np": 0}, "pc:左+弦+涩+紧+迟": {"o": "左弦涩紧迟脉总起来主寒凝气滞、气逆食滞交阻之实证。其脉象以紧迟涩为主，紧迟应寒，涩应气滞食积；左弦紧突出寒邪引动厥气上逆、肝脉拘急，右迟涩侧重寒凝气滞、食滞交阻中宫。三类病机相互关联：新寒外受为诱因，寒凝导致气滞，气滞则厥气上逆，食滞交阻中宫，胃气不得下降，故见胸脘痛、呕吐拒按、形寒怯冷、苔灰腻等症。脉象左右合参，弦紧与迟涩并见，正合寒、气、食交阻之病机，治当散寒理气、和胃消滞。", "c": [{"name": "主寒凝气滞", "desc": "脉紧迟涩，紧主寒，迟主寒凝，涩主气滞血涩。原文谓新寒外受，寒邪引动厥气上逆，右迟涩主寒凝气滞、食滞交阻中宫，形寒怯冷、苔灰腻，皆寒凝气滞之征。"}], "n": {"主寒凝气滞": 1}, "a": {"390": "主寒凝气滞"}, "t": 1, "np": 0}, "c:数+细+沉+弱": {"o": "沉细数弱脉总起来主阴虚内热与痰热内蕴两类病机。沉细为阴伤，数弱为虚热，故见口渴、手心热、喜暗处等阴虚内热之象；若痰热内结，阻滞气机，则脉可渐伏而妄语，形成痰热蒙蔽心窍之证。两者可并存，阴虚为本，痰热为标，痰热又可加重阴伤，故治疗需兼顾下痰与养阴。", "c": [{"name": "主阴虚内热", "desc": "脉沉细数弱，沉细为阴液亏虚，数弱为虚热内生。原文见口渐渴、手心热、喜暗处，皆阴虚内热之象，故脉主阴伤虚热。"}], "n": {"主阴虚内热": 1}, "a": {"3666": "主阴虚内热"}, "t": 1, "np": 0}, "pc:左+数+细+微+弱": {"o": "左脉细弦而数、右脉细数微弱，总属虚实夹杂之候。细数主阴伤热炽，弦主郁，弱主气衰，故其病机以火热劫烁肺胃、阴津大伤为核心，兼有气机郁滞与正气虚弱。火热内炽则阴津受灼，气郁不达则邪热郁结，气衰则正虚无力托邪，三者相互影响，形成热炽、阴伤、气郁、气衰并见的复杂局面。原文'细数主阴伤热炽，弦主郁，弱主气衰'已明示脉象与病机对应，而'火热劫烁肺胃，阴津大伤'则统括其要。诸类之中，阴伤热炽与火热劫烁肺胃互为因果，气郁与气衰则加重邪热郁结与正虚，故临证需兼顾清热养阴、解郁益气。", "c": [{"name": "主阴伤热炽", "desc": "脉细数，细为阴血不足，数为热盛，合示阴液耗伤而火热内炽。原文'细数主阴伤热炽'，症见烦热、口渴喜凉饮、舌白质红尖红点，皆阴伤热炽之象。"}], "n": {"主阴伤热炽": 1}, "a": {"7397": "主阴伤热炽"}, "t": 1, "np": 0}, "pc:左+大+沉+浮+小": {"o": "左·大沉浮小脉在此案中总主虚与疟邪未净。患者年高形弱，劳心劳力，气血阴液亏耗，故左脉沉小、右脉浮濡无力，主虚；疟邪内扰，脾部弦洪，主疟。虚分阴虚与气虚：左脉沉小数主阴血不足、虚热内扰；右脉浮濡无力主脾肺气虚。疟邪未净则见弦洪，疟去后脉转缓弱，示邪退正虚。诸类相互关联：正虚是基础，疟邪乘虚而作，虚象贯穿始终，邪去则虚象更显。", "c": [{"name": "主虚", "desc": "左脉沉小、右脉浮濡无力，皆属虚象。年逾六十形弱，劳心劳力，气血耗伤，故脉沉小无力；右脉浮濡示脾肺气虚。疟去后脉缓弱，亦为正虚之征。"}], "n": {"主虚": 1}, "a": {"15100": "主虚"}, "t": 1, "np": 0}, "c:数+虚+涩+短": {"o": "短涩虚数脉总属虚损之象，以气阴两虚、虚热内扰为核心。短主气虚，涩主阴亏血少，虚数主阴液内亏、虚热内扰。四者相合，反映气阴两伤、虚热内生之病机。本例八十五岁郁勃之体，厥阳司升，阴液内亏，秋燥将至，易伤肺金，故预进清金益胃，恐延肺痿。各分类之间相互关联：气虚推动无力则脉短，阴亏血少则脉涩，阴虚生内热则脉虚数，久则肺阴受损，形成肺痿倾向。总以虚为本，热为标，病位在肺胃，涉及气阴。", "c": [{"name": "主气虚", "desc": "脉短为气虚之象。原文谓“短为气虚”，患者年高体衰，郁勃伤气，故脉短。气虚推动无力，故脉道短缩，不能满部。"}], "n": {"主气虚": 1}, "a": {"16311": "主气虚"}, "t": 1, "np": 0}, "pc:左+弦+滑+洪+硬": {"o": "左·弦滑洪硬脉在此案中实际表现为弦硬而长、数近七至，故所主病机以热盛、阴虚、气血两亏及正虚邪恋为主。数脉主热，亦主阴虚；弦硬而长为气血两亏、邪热炽盛之征；正气虚损不能拒邪亦现数，故见正虚邪恋。诸类之间相互关联：邪热炽盛可耗伤阴液，致阴虚有热；热盛又可损气耗血，致气血两亏；气血阴亏则正气虚损，无力拒邪，形成正虚邪恋、虚实夹杂之局。总起来说，此脉主热盛阴伤、气血亏虚、正虚邪恋之复杂病机，属本虚标实、虚实夹杂之候。", "c": [{"name": "主热盛", "desc": "脉数近七至，且伴面红、舌黑、热甚，显系邪热炽盛。数脉主热，弦硬而长亦为邪热炽盛之征，故此类脉象反映阳明热炽或气分热盛之病机。"}], "n": {"主热盛": 1}, "a": {"20608": "主热盛"}, "t": 1, "np": 0}, "pc:寸+微+涩+小+短": {"o": "寸·微涩小短脉总属虚候，主五脏虚衰、气血不足及阳虚外浮。其脉象轻取或滑，重按微涩小短，反映虚阳浮越于上而根本内亏。所主病机以脏虚为核心：微为气衰，涩为血少，小短为脉道不充，合而示正气内衰；举指滑而按之微，又示虚阳外浮、不能内守。三者相互关联：脏虚为根本，气血不足为物质基础，阳虚外浮为虚象之外露。故临床见此脉，当责之寸部所候心肺上焦之虚，并结合全身症状辨其脏虚、气血虚或阳虚浮越之偏重。", "c": [{"name": "主脏虚", "desc": "原文引华元化论脏虚，诊脉“举指而滑，按之而微”，又言“按之沉小微弱短涩软濡，俱为脏虚”。微涩小短脉按之无力，为正气内衰、根本不足之象，故主五脏之虚，尤以寸部候上焦脏气虚衰。"}], "n": {"主脏虚": 1}, "a": {"22693": "主脏虚"}, "t": 1, "np": 0}, "c:细+沉+虚+小": {"o": "虚细沉小脉总属气血虚衰、脉道不充之象，尤以亡血失血为核心病机。其脉虚细主血虚，沉小主气弱，故金疮出血太多见此脉为脉证相应，预后良好。然同一脉象若见于瘀血内阻之证，则提示正气已衰，无力抗邪，脉与病机不符，预后不良。原文汇集《内经》《金匮》《脉经》论金疮跌仆之脉，要旨在“脉病相应则生，不相应则死”。虚细沉小脉所主病机可归纳为亡血、气血两虚、瘀血兼正虚及脉证相应四类，四者相互关联：亡血与气血两虚为脉象直接对应之病机，瘀血兼正虚为脉证不符之变局，脉证相应则贯穿诸类，决定预后吉凶。", "c": [{"name": "主亡血", "desc": "虚细沉小脉主失血后脉道空虚。原文引《脉经》金疮出血太多，脉见虚细沉小者生，因血去脉空，脉象与病机相应；又引《金匮》寸口浮微而涩主亡血，涩为血少，微为阳衰，皆亡血之征。"}], "n": {"主亡血": 1}, "a": {"24075": "主亡血"}, "t": 1, "np": 0}, "c:数+浮+紧": {"o": "浮紧数脉总属表邪、热壅、寒束相兼之脉。浮主病位在表，紧主寒主痛主闭，数主热主邪正相争，三象合见，总以表里同病、寒热错杂为枢。其所主病机，或为单纯表邪未解（如太阳伤寒），或为湿热挟滞壅于肠胃、肌肤、筋骨，或为寒热交织、表盛里虚，或为邪壅气血而痛，或为痰痧闭阻心窍。各类之间以“表邪”为共同前提，以“热壅”与“寒束”为矛盾两端，以“壅滞不通”为共同转归，故临床既可见于外感初起，亦可见于湿热痢、黄疸、周痹、癫痫等杂病。总以解表、清热、化湿、行滞为治，随寒热偏盛而权衡。", "c": [{"name": "主表邪", "desc": "浮紧数脉浮主表，紧主寒束，数主邪正相争，合为表邪之征。原文如“浮紧而数者，即表邪也”，“邪热在表”，“表邪未解”，均以浮紧数断表邪未解，或风寒外束，或时气袭表，病位在肌表太阳经。"}, {"name": "主湿热壅滞", "desc": "浮紧数脉浮紧应外湿束表，数应内热郁蒸，合示湿热挟滞、表里同病。原文湿热挟滞互阻肠胃成噤口痢，湿著于外热郁于内发黄，湿热搏结筋骨为周痹，均以浮紧数主湿热壅滞、气血不畅。"}, {"name": "主痰痧闭阻", "desc": "浮紧数脉紧主痧毒郁闭、痰气交阻，数主热，浮主邪在表。原文猪痫风“痰浊内伏、痧毒闭阻心窍”，脉浮紧而数，放痧后脉平，继以滚痰丸取效，示紧数由痧毒痰浊壅遏所致。"}], "n": {"主表邪": 6, "主湿热壅滞": 2, "主痰痧闭阻": 1}, "a": {"197": "主表邪", "435": "主表邪", "3693": "主表邪", "6136": "主湿热壅滞", "6431": "主湿热壅滞", "15298": "主表邪", "18468": "主痰痧闭阻", "22885": "主表邪", "25498": "主表邪"}, "t": 9, "np": 0}, "c:数+细+软": {"o": "细软数脉总属虚象，以阴血亏虚为本，虚火、郁热为标。细主阴伤，软主气虚，数主热，三者并见，反映正虚而热扰的复合病机。其具体所主，约分五类：一为虚火内扰，火性上炎下迫，充斥三焦；二为阴亏火旺，水不制火，虚热内生；三为虚风内动，阴亏火旺，风火相煽而致搐动；四为邪郁伤阴，虚体感邪，邪郁化热，劫灼阴津；五为气阴两虚，病后邪去正虚，气阴未复。五类之间，以阴亏气虚为共同基础，虚火、郁热、风动为不同转归，或虚火独立为病，或兼夹外邪，或虚风内动，总不离“虚”与“热”二字。", "c": [{"name": "主虚火", "desc": "细软数脉中细软主虚，数主虚火。原文如谓“虚火非上扰即下迫”，上扰则耳鸣，下迫则梦泄，虚火充斥三焦；经漏脉细软带数，为营血亏虚、虚热内生；脉细软数，为心阴内亏、虚热扰神。皆因虚致火，火又伤正。"}, {"name": "主阴亏火旺", "desc": "细为阴液亏虚，数为火旺，软为气弱。原文六脉细数而软，断为“阴亏火旺、虚风内动”；少年白发咽嗌不爽，脉细数而软，示“水不荣木，阴液久亏”而生内热；左脉细软而数，为“阴分素亏，源流两涸”而燥热内生。总属阴亏于下，火炎于上。"}, {"name": "主虚风内动", "desc": "细数软脉主阴亏火旺，火旺则风动。原文“虚风游走，风化为火，风愈高火愈炽”，见项强神烦、不能起坐；温邪病脉细数而软，见手指搐动、喃喃自语，为阴伤热郁、内风欲动。皆由阴亏火旺，风火相煽而致痉厥搐动。"}, {"name": "主邪郁伤阴", "desc": "细数而软，细主阴伤，数主热，软主虚体。原文温邪、湿邪病缠一候，发热不退，脉细数而软，舌白黄少津，为“虚体邪郁，不易外解而易传里”，邪郁化热，劫灼阴津；疟邪内陷，脉软细而数，为“邪陷伤阴，营损化热”。总属正虚邪郁，阴液受灼。"}, {"name": "主气阴两虚", "desc": "细软为气血不足，数而不洪为阴亏有热。原文脉细软数，倦怠不嗜食、寤寐纷纭，为“邪去正虚，心阴内亏”，脾胃未复；经漏脉细软带数，病象由实转虚，营血亏虚；脉细数而软，为阴液久亏而气亦不足。皆示气阴两伤，虚热内扰。"}], "n": {"主虚火": 1, "主阴亏火旺": 2, "主虚风内动": 1, "主邪郁伤阴": 4, "主气阴两虚": 1}, "a": {"9127": "主虚火", "9214": "主邪郁伤阴", "9420": "主邪郁伤阴", "10535": "主阴亏火旺", "10547": "主邪郁伤阴", "12420": "主虚风内动", "12449": "主阴亏火旺", "13337": "主邪郁伤阴", "18055": "主气阴两虚"}, "t": 9, "np": 0}, "pc:右+数+弦+小": {"o": "右·数弦小脉总以弦、数、小三象合参，主病机涉及肝郁、郁热、痰湿、阴虚、脾虚、肝火犯肺及疟邪等。弦主肝郁气滞，数主热，小主阴伤或湿阻。诸类之间常相互兼夹：肝郁化热则弦数并见；肝火犯肺则木火刑金；脾虚湿困则小弦带涩；阴虚火旺则小数；痰湿内盛则小弦而滑。总属本虚标实、寒热错杂之候，以肝郁气滞、郁热内蕴为核心，兼见脾虚、阴虚、痰湿等，临证需脉症合参，辨其主次。", "c": [{"name": "主肝郁气滞", "desc": "弦脉为肝郁气滞之象，右脉弦或左弦右弦并见，多因情志不遂、肝气横逆，如案中“肝横气滞”“肝胃乘扰”“肝邪上扰”等，气机不畅故脉弦。"}, {"name": "主痰湿内盛", "desc": "小脉主湿，弦数兼小，痰湿内蕴。案中“体肥多湿多痰”“聚湿成饮”“痰热胶固”“右小滑”等，湿浊痰饮内停，脉道不利故小，痰阻气机故弦。"}, {"name": "主阴虚火旺", "desc": "小脉主阴伤，数主火旺，右小弦数见于阴虚呛咳、失血、咽痛等症。原文“小主阴伤”“阴虚内热”，阴液亏虚，虚火内动，脉细小数。"}, {"name": "主脾虚湿困", "desc": "右脉候脾，小弦带涩或小弦数，主脾虚湿困。案中“脾胃必虚”“中气不足”“脾不运行”等，脾虚失运，湿浊内停，脉小弦而涩。"}, {"name": "主肝火犯肺", "desc": "弦数主肝火，右脉候肺，右小弦数示木火刑金。原文“木火刑金”“肝之左升太过，肺之右降不及”，肝火犯肺，灼伤肺络，故咳呛咯血。"}, {"name": "主疟邪痰湿", "desc": "疟发连枝，肝邪上扰，湿从膜原外腾为疟。右小弦数，左关弦甚，疟后津伤中气不足，痰湿内蕴，脉小弦数，主疟邪未彻、痰湿内阻。"}], "n": {"主肝郁气滞": 1, "主痰湿内盛": 2, "主阴虚火旺": 1, "主脾虚湿困": 2, "主肝火犯肺": 1, "主疟邪痰湿": 1}, "a": {"1123": "主脾虚湿困", "2399": "主肝火犯肺", "2616": "主痰湿内盛", "2621": "主肝郁气滞", "2659": "主脾虚湿困", "2760": "主疟邪痰湿", "15950": "主痰湿内盛", "17072": "主阴虚火旺"}, "t": 8, "np": 0}, "c:弦+微+弱": {"o": "微弱弦脉总起来主虚中夹实、本虚标实之证。微弱为气血阴阳不足之本，弦为肝旺、肝风、寒湿或气滞之标，涩则兼气滞血瘀。各类病机相互关联：气血虚少则肝失濡养而肝旺，肝旺化火伤阴，虚火复耗气血，形成虚火相兼；血虚脉道不充则血行涩滞，兼见气滞血瘀；中气虚弱则寒湿内侵，或虚风内动。故微弱弦脉所主，以虚为本，以肝旺、血瘀、寒湿、虚风为标，虚实夹杂，临证需辨脉之有力无力及兼象，分其主次。", "c": [{"name": "主虚", "desc": "微弱脉为气血阴阳不足之象。原文如'微弱为气阴两虚'、'微弱主中气虚弱'、'微弱主虚'，均以微弱直接指虚。脉力微弱反映正气亏虚，气血不充脉道，故主虚证，可涉及气阴两虚、中气虚弱等。"}, {"name": "主寒湿", "desc": "微弱而弦主中虚寒湿。原文'弦主寒湿内侵或饮邪'，脉微弱而弦，伴跗肿便溏、痰多食少、不渴无苔，乃中虚寒湿为患。弦脉主寒湿饮邪内侵，微弱主中气虚弱，故主寒湿内盛。"}, {"name": "主虚风", "desc": "微弱而弦主虚风内动。原文'微弱为气阴两虚，弦为虚风内动'，气阴两虚则肝失濡养，虚风上扰，脉见微弱而弦。此属本虚标实，虚风内动之候，与实风不同。"}], "n": {"主虚": 1, "主寒湿": 1, "主虚风": 3}, "a": {"4183": "主虚", "13384": "主虚风", "13780": "主虚风", "13929": "主寒湿", "13969": "主虚风"}, "t": 5, "np": 0}, "c:弦+细+弱": {"o": "细弦弱脉总属阴脉，以虚为本，兼见弦象所主之郁、饮、痛、风等。细弱主气血阴阳亏虚，弦主气郁、饮邪、寒痛及肝风阳浮。诸段所主病机可归纳为虚、饮、寒、气郁、阳浮风动、湿热痰火六类。其中虚为根本，或为营血大亏，或为气阳虚寒，或为脾虚气弱；弦则因虚而郁、因虚而饮停、因虚而寒凝、因虚而阳浮风动。虚与饮、寒常相合，本虚标实；虚与郁、风相兼，为阴亏阳浮；虚中夹湿热痰火，则属邪退正伤或实转虚之动态过程。诸类之间以虚为核心，弦象为兼，虚实寒热错杂，总以扶正潜阳、温化疏利为治要。", "c": [{"name": "主虚", "desc": "细弱脉为气血阴阳亏虚之象。原文多言细弱主营血大亏、气不足息、脾虚气弱、阳气不足。如脉弦细而弱，断为营血大亏；细弱为气阳虚寒、营血不足；细弱示营虚水亏、脾虚气弱。故细弱之象总主虚，涵盖气血阴阳之不足。"}, {"name": "主寒", "desc": "弦迟细弱脉中迟主寒，细弱主虚，弦主痛及饮，合为阳虚寒盛、沉寒锢冷之机。原文述阳气大虚，寒凝与阳虚互为因果，寒凝更伤阳。如脉细弦弱，中气虚寒由气分伤及血分，肢冷腹痛，痢下瘀紫血水，正合虚寒入血之候。"}], "n": {"主虚": 4, "主寒": 1}, "a": {"9112": "主虚", "10465": "主寒", "11640": "主虚", "13334": "主虚", "13867": "主虚"}, "t": 5, "np": 0}, "c:小+缓+结": {"o": "缓小结脉总以“缓”为胃气尚存之象，“小结”为邪滞正伤之征，故其病机以脾胃虚实为核心。四段中，泄注、泄痢、水谷痢均见“脉缓时小结者生”，强调缓为脾脉、胃气未败，小结示邪滞而正未大伤，属邪滞正伤、脾虚湿盛之轻证，预后良好；若脉转为浮大数，则正脱邪盛，主死。另伤寒、温病见沉小、细小难得之脉，则属正虚邪陷，与缓小结之“缓”不同，但同属正虚不能抗邪之机。诸类之间，胃气存为吉兆基础，邪滞正伤、脾虚湿盛为常见病机，正虚邪陷为危重转归，总以脉证相应、胃气存亡为辨生死之要。", "c": [{"name": "主胃气存", "desc": "缓脉为脾胃本脉，缓而时小结，示胃气尚存、邪滞未甚。原文如泄注、泄痢、水谷痢皆以“脉缓时小结者生”，与浮大数对举，说明缓小结是胃气未败、脉证相应的佳兆。"}, {"name": "主正虚邪陷", "desc": "伤寒、温病见沉小、细小难得之脉，示正虚不能抗邪，邪气内陷。原文以浮大沉小判吉凶：伤寒热盛脉浮大者生，沉小者死；汗后脉沉小者生，浮大者死；温病脉细小难得者死，皆属正虚邪陷之候。"}], "n": {"主胃气存": 3, "主正虚邪陷": 1}, "a": {"19209": "主胃气存", "21160": "主胃气存", "21824": "主正虚邪陷", "22217": "主胃气存"}, "t": 4, "np": 0}, "c:数+滑+和": {"o": "滑数和脉总起来主痰热、燥火、阴亏火旺及余邪留恋四类病机，核心为肺胃痰热渐化而余焰未清，兼肝阴亏耗、木火易炽。右脉滑数较和，右候肺胃，滑主痰、数主热，示痰热渐退而未净；左脉弦数不靖，左候肝胆，示阴液素亏、肝热内炽。四类之中，痰热与燥火偏于标实，阴亏火旺偏于本虚，余邪留恋则贯穿病程始终。诸类相互关联：痰热燥火灼津则阴亏，阴亏火旺又生痰燥，余邪留恋使痰热燥火未能尽澈。脉象由滑数较和、弦数不靖渐至弦数已缓、滑数亦和，反映邪退正复之转机，但余燥未清，仍须清化。", "c": [{"name": "主余邪留恋", "desc": "伏温渐解，温热已去其七，肺炎亦消，然舌苔化而未净、小溲未清、咳嗽痰鸣减而未止，右脉滑数较和示余邪未澈。滑数和脉主伏邪余焰留恋气分，肺胃输化失职，痰热未净，故虽险关已逾而余焰未清。"}], "n": {"主余邪留恋": 3}, "a": {"65": "主余邪留恋", "66": "主余邪留恋", "67": "主余邪留恋"}, "t": 3, "np": 0}, "c:弦+芤+促": {"o": "弦促芤脉总起来主藏阴内虚、阳动气泄、肝郁血溢之证。弦主肝郁，促主阳升气泄，芤主阴血内虚，三脉合见，反映心、脾、肝三脏阴亏，阴不制阳，阳动气泄，血不循经而溢出上窍。其病机核心是“藏阴内虚，阳动乃溢”：阴血亏虚为本，肝郁气滞为诱因，阳升气泄为动力，最终导致上部出血。原文强调病已数年、纳谷不旺、望色萎黄少膏泽，说明久病中气亦虚，但非少壮阴火可比。治疗以归脾汤去温燥加白芍，和肝脾之阴，体现王道养正之法。四类病机中，藏阴内虚是基础，肝郁与阳升气泄是促发条件，血溢上窍是最终结果，彼此关联，共同构成该脉的完整病机链条。", "c": [{"name": "主肝郁", "desc": "脉弦为肝郁之象。原文两段均明言“弦主肝郁”，且患者情志不适则血溢上窍，说明肝气郁结、疏泄失常是发病的重要环节。弦脉应肝，主气机郁滞，与情志不遂、气郁化火动血密切相关。"}], "n": {"主肝郁": 2}, "a": {"561": "主肝郁", "4373": "主肝郁"}, "t": 2, "np": 0}, "c:细+浮+弱": {"o": "浮细弱脉总属虚象，以气血两虚、血衰为核心，兼见表虚不固、虚风外扰与下焦亏虚。浮为气虚外浮或虚阳上浮，细弱为阴血衰少、脉道不充，故非表实而主虚。其病机层次：下焦肾肝精血亏虚为血衰之根；气血不足则卫外不固，形成表虚之证；血虚不荣、虚风乘袭，又见虚风外扰之标。原文下疳久耗阴精，耳鸣身痛，脉浮细弱，断为气血两虚、虚人外浮；痘证表虚脉浮细而弱，治宜温补。下属浮细缓弱脉总述强调血衰为本、虚风为标、下焦亏虚为根；浮弦细弱脉则兼气虚、气郁与脾虚肝乘。诸类相互关联，总以虚为本，浮为虚象外露，细弱为不足之体，临床当温补气血、固护下焦，不可误作表实而攻散。", "c": [{"name": "主气血两虚", "desc": "浮细弱脉中细弱为阴血衰少、脉道不充，浮为气虚外浮。原文下疳久耗阴精，耳鸣身痛，脉浮细弱，断为气血两虚；表虚痘证脉浮细而弱，亦属气血不足、卫外不固。故主气血两虚，以血衰为核心。"}], "n": {"主气血两虚": 2}, "a": {"3009": "主气血两虚", "23846": "主气血两虚"}, "t": 2, "np": 0}, "c:细+微+弱": {"o": "微弱细脉总属正气虚衰之候，以阳气衰微、脾胃气钝为核心病机。微为阳衰，弱为气馁，细为血少，三象相合，反映阳气失于护卫、鼓运无力。其具体所主，一为阳气衰微，见形冷汗泄、寒栗汗出；二为脾胃气钝，见不饥少纳、脘腹常痞、泄气自舒；三为正虚非邪，舌明润、不喜饮汤，非邪结客热之比。三者相互关联：阳气衰微则卫外不固而汗泄寒栗，阳失鼓运则脾胃气钝而纳痞，正虚则非邪实，故治宜理中汤专理脾胃阳气。此脉总以虚证为纲，阳气虚衰为要，与下属细数微弱、微细迟弱、沉细微弱等脉所主虚寒、气阴两虚、虚损等证一脉相承，皆属正气亏虚之候。", "c": [{"name": "主阳气衰微", "desc": "脉微弱而细，微为阳衰，弱为气馁，细为血少，合见形冷汗泄、寒栗汗出、不饥少纳、脘腹常痞，皆阳气失护卫、失鼓运之象。原文谓'阳气失护卫'则寒栗汗出，'阳失鼓运'则脾胃气钝，故脉主阳气衰微，非邪结客热之比。"}], "n": {"主阳气衰微": 2}, "a": {"4568": "主阳气衰微", "4907": "主阳气衰微"}, "t": 2, "np": 0}, "c:弦+滑+微": {"o": "弦微滑脉总起来主风、湿、痰、火相互搏结为患，其病机核心为风湿内郁与风阳上冒两类。弦脉主风、主饮、主肝，滑脉主湿、主痰、主火，微滑则示痰湿较轻或兼阴伤。两段所载，一为风湿袭脾，水湿泛溢而见足肿麻木；一为阴虚阳亢，风木升动、痰火内郁而致卒厥迷愦。二者虽病位有脾与肝之别，但均以风痰湿浊为患，且常兼本虚标实之象。弦微滑脉所主病机，总以风痰湿火为标，脾弱阴虚为本，体现了虚实夹杂、痰气壅滞的特点。", "c": [{"name": "主风湿困脾", "desc": "脉弦微滑，弦主风、主饮，滑主湿、主痰。原文载“风与湿袭入脾脏”，脾主四肢肌肉，风湿困脾，水湿泛溢则见足肿按之坚硬、肌肤麻木不仁、头面微肿。脉象弦滑相应，反映风湿内郁、水湿泛溢之机。"}], "n": {"主风湿困脾": 2}, "a": {"8041": "主风湿困脾", "8154": "主风湿困脾"}, "t": 2, "np": 0}, "c:弦+滑+实": {"o": "弦滑实脉总起来主邪热内传、腑实热结之证，兼涉痰热内壅与气机郁结。其脉弦主气机壅塞、热郁气结，滑主痰热内壅，实主邪气盛而正未虚。三者相合，多见于外感热病邪归阳明、燥实内结之候，如原文所载石芷卿患感，前医升散后热退复热，俟邪归于府，脉来弦滑而实，径用承气汤下之，下后府垢行而经热始显。此脉虽腹不坚满，但脉实为可下之凭，说明其主病机以腑实热结为核心，痰热与气郁为兼夹。各类之间相互关联：气郁热结为邪热内传之始，痰热内壅为病理产物，腑实热结为最终转归，共同构成弦滑实脉所反映的实热壅盛、腑气不通之病机格局。", "c": [{"name": "主腑实热结", "desc": "脉弦滑而实，为邪热内传阳明、燥实内结之征。弦主热郁气结，滑主痰热内壅，实主邪气盛而正未虚。原文载'邪归于府，脉来弦滑而实，径用承气汤下之'，虽腹不坚满，但脉实为可下之凭，下后'府垢行而经热始显'，正合腑实热结之机。"}], "n": {"主腑实热结": 2}, "a": {"13000": "主腑实热结", "13804": "主腑实热结"}, "t": 2, "np": 0}, "pc:六+细+微+伏": {"o": "六·细微伏脉总属虚实夹杂之候，以气血不足为本、邪闭气机为标。微细主气血亏虚，伏主邪气内闭，二者并见，提示正虚与邪闭并存。所主病机主要有三类：一为气血不足，脉道不充；二为邪闭气机，阳气不达；三为痧毒深伏，络脉壅塞。三者相互关联：气血不足则抗邪无力，邪易内闭；邪闭日久又耗伤气血，形成恶性循环。临床见微细伏脉，当细辨虚实主次，如暑热秽毒内闭心包、痧毒深伏等，皆可致此脉，治疗需扶正与透邪并重。", "c": [{"name": "主气血不足", "desc": "脉微细主气血亏虚。原文18450段明言“微细主气血不足”，因暑热秽毒耗伤气血，脉道不充，故见微细。此与伏脉同见，提示正虚为病本之一。"}], "n": {"主气血不足": 2}, "a": {"18450": "主气血不足", "18470": "主气血不足"}, "t": 2, "np": 0}, "c:浮+微+涩": {"o": "浮微涩脉总属阴血亏虚、气随血耗之候。浮为气虚外浮，微为阳衰，涩为血少行滞，三者相合，核心病机为亡血、汗出及金疮失血。原文两条均以'寸口脉浮微而涩，法当亡血，若汗出'为纲，并补充无汗而身有疮、刀斧所伤亡血者亦见此脉，说明其主病以血虚津伤为本。此外，该脉兼搏坚而长等象时可主瘀血坠伤，属脉象兼夹之变。各类之间以阴血亏虚为共同基础：亡血与汗出同源，金疮伤为亡血之因，瘀血则为兼见之变，故临床须结合兼脉及病史辨别。", "c": [{"name": "主亡血", "desc": "浮微涩脉主阴血亏虚。浮为气虚外浮，微为阳衰，涩为血少行滞，合则血去脉道不充。原文'寸口脉浮微而涩，法当亡血'及'金疮出血太多'皆以涩微示血脱，故主亡血。"}], "n": {"主亡血": 2}, "a": {"24075": "主亡血", "25435": "主亡血"}, "t": 2, "np": 0}, "pc:六+弦+洪+缓": {"o": "六·弦洪缓脉总起来主风热内陷、阳气不布、痰湿阻滞之病机。弦脉主风，洪脉主热，缓脉主湿，三脉相合，按之无力，反映风热之邪下陷阴中，阳气不能正常运行，同时痰湿内阻。风热内陷导致阳气不布，阳气不布又加重痰湿阻滞，三者相互影响。原文以麻木昼减夜甚、开目则麻退为特征，说明病机关键在于气机不畅而非单纯外风。脉象弦洪缓而无力，正是风热、痰湿与阳气不足并见的综合表现。", "c": [{"name": "主风热内陷", "desc": "脉弦洪缓相合，弦在其上，按之无力，为风热下陷入阴中。弦主风，洪主热，风热内陷，阳气不布，故见麻木昼减夜甚、烦躁等症。"}], "n": {"主风热内陷": 1}, "a": {"3918": "主风热内陷"}, "t": 1, "np": 0}, "c:数+细+紧": {"o": "细紧数脉总属正虚邪盛、本虚标实之候。细主阴伤血少，紧主邪结寒凝，数主热或虚性亢奋。三者合参，揭示元气已亏而邪气深入之病机。其具体所主，一为正虚邪盛，病深日久，精神殆尽；二为阴伤热结，阴液耗伤而邪热内结；三为胃气衰败，饮食不进，化源告竭。三类均以正虚为本、邪盛为标，细紧数并见，提示病情深重，预后多凶。", "c": [{"name": "主正虚邪盛", "desc": "细为阴伤，紧主邪结，数主热，三者并见，反映元气已竭而邪气深入。原文见似疟非疟、饮食不进、精神殆尽，脉细紧而数，乃病深日久，正不胜邪，胃气已败之候，预后凶险。"}], "n": {"主正虚邪盛": 1}, "a": {"3990": "主正虚邪盛"}, "t": 1, "np": 0}, "c:细+滑+微": {"o": "细微滑脉总起来主虚实夹杂之候，以虚为本，以痰湿为标，并可主妊娠。细主阴血不足，微主阳气衰微，滑主痰湿内阻，微滑则痰浊较轻。原文一例产后经闭、形瘦面紫、呕吐声哑、手指挛拳，脉细微近滑而尺脉不绝，断为妊娠恶阻，说明此脉既可见于气血亏虚、痰湿中阻之杂病，又可为妊娠之常脉。三类病机相互关联：虚为根本，痰湿为标，妊娠则因胎气上逆、胃失和降而现此脉。临证须结合尺脉不绝、形症特点，辨其虚实及妊娠可能，不可一概视为虚劳或痰病。", "c": [{"name": "主妊娠", "desc": "脉细微近滑而尺脉不绝，是妊娠恶阻之征。原文谓“脉虽细微，似近于滑，又尺脉不绝，乃妊娠也”。形瘦面紫、呕吐声哑、手指挛拳，皆胎气上逆、胃失和降所致，故脉见细微滑而尺部不绝。"}], "n": {"主妊娠": 1}, "a": {"4045": "主妊娠"}, "t": 1, "np": 0}, "pc:左+微+弱+促": {"o": "左·微弱促脉总起来主阳伤津劫、里热湿蕴之复合病机。左脉弱为卫阳大伤、胃津被劫，属虚；右脉促为里热未清、湿蕴化热，属实。原文因伏暑冒凉发疟，误用辛温大汗，致汗多伤阳、劫津，而湿蕴未化、里热未清，故脉见左弱右促。四类病机中，阳伤与津劫同源于汗多，互为因果；里热与湿蕴同源于中虚聚湿，湿郁化热。总属虚实夹杂、燥湿并见之候，治当甘缓，不可骤补。", "c": [{"name": "主阳伤", "desc": "左脉弱为卫阳大伤之征。原文载辛温大汗后“汗多卫阳大伤”，左脉弱即阳气虚损、鼓动无力之象，故主阳伤。"}], "n": {"主阳伤": 1}, "a": {"4567": "主阳伤"}, "t": 1, "np": 0}, "c:数+虚+促": {"o": "虚数促脉总属虚损危候，主阴阳并亏、虚阳浮动、脏气衰败。虚为阴阳气血俱不足，数为阴不敛阳而虚阳上浮，促为脏气衰败、真元欲脱之象。三者相互关联：病久阴阳并亏是根本，虚阳浮动为阴虚阳越之标，脏气衰败则因虚致危，层层递进。原文脉证俱危，强调肾不纳、肺不降、浮阳上越、自汗气急等症，皆由虚数促脉所主之阴阳离决、脏真失司所致，故为危重之脉。", "c": [{"name": "主阴阳并亏", "desc": "脉虚为阴阳气血俱虚之象。原文谓“虚为阴阳并亏”，病久脏气耗伤，阴阳两虚，故脉虚而数促并见，主脏真亏损。"}], "n": {"主阴阳并亏": 1}, "a": {"9628": "主阴阳并亏"}, "t": 1, "np": 0}, "c:数+微+软": {"o": "微数软脉总属正虚之候，以阳气衰微、气弱为本，虚热与阴亏为标。微为阳衰，软为气弱，数虽主热，但微软并见则为虚性之数，非实火。原文见肢冷畏寒、汗出不已、舌全光，断为“一派虚象”，强调扶正为要。故其病机以阳衰气弱、表卫不固为主，虚性数热与阴液亏虚为兼。三者相互关联：阳衰则卫外不固而汗出，汗出则阴液更伤，阴亏则虚热内生，虚热又致数脉。总以正虚为核心，虚热、阴亏皆由阳衰气弱所派生，属虚实夹杂中以虚为主之脉象。", "c": [{"name": "主阳衰气弱", "desc": "脉微为阳气衰微，软为气弱不振。原文见肢冷畏寒、汗出不已，显系阳气式微、卫外不固；舌全光亦示阴液亏耗。故微数软脉主正虚阳弱、表卫不固之病机。"}], "n": {"主阳衰气弱": 1}, "a": {"9225": "主阳衰气弱"}, "t": 1, "np": 0}, "pc:六+滑+缓+长": {"o": "六·滑缓长脉总属平脉范畴，主气血充盛、脾胃健运，为体质强健之征。缓滑而长，三部俱见，示气血旺盛、中焦调和，故虽年届五十而天癸不衰，肌肤润泽。左寸关兼见弦数，则为肝郁化热之微兆，属兼夹之轻症，与多产、情志相关。三类之中，前二者为脉之本象，主生理之常；后者为兼见之象，主轻微病理。总以正气充盛为主，兼有肝郁化热为辅，非危重病脉。", "c": [{"name": "主气血充盛", "desc": "脉缓滑而长，为气血充盈之象。缓主胃气调和，滑主血盛，长主气旺，故原文谓‘气血充盛’，年五十而天癸不衰，肌肤润泽如三十许人，显系气血旺盛之平脉。"}], "n": {"主气血充盛": 1}, "a": {"13454": "主气血充盛"}, "t": 1, "np": 0}, "c:数+空+促": {"o": "空促数脉总起来主热盛阴伤、营血暴脱之病机。其脉空软为血脱脉虚之象，促数为热邪未清之征，二者并见，反映热邪未解而营阴已伤、血脱于下的复杂局面。原文所述冬温失于清解，误服辛热温燥，致崩血一阵，脉见空软促数，苔黑舌绛，足冷息微，正是热盛、阴伤、血脱交织之候。三类病机中，热盛为始动因素，热迫血妄行则致血脱，血脱则阴伤，阴伤又易生内热，三者互为因果，形成热盛阴伤血脱的恶性循环。然本案汛断十载，阴精基础尚存，故虽见危候而可治。", "c": [{"name": "主热盛", "desc": "脉促数乃热邪内盛、迫急不安之象。原文冬温失于清解，误服辛热温燥，致热邪深入，脉见促数，反映热盛于内，鼓动血脉，故主热盛。"}], "n": {"主热盛": 1}, "a": {"14049": "主热盛"}, "t": 1, "np": 0}, "pc:关+弦+细+涩": {"o": "关·弦细涩脉总属虚实夹杂之候，以肝旺、脾湿、气血不足为基本病机。弦主肝旺，细主不足，涩主湿滞，三脉并见，反映肝气横逆、脾虚湿困、气血运行不畅。肝旺则疏泄失常，脾湿则运化失职，气血不足则荣卫不利，故临床可见胸腹不舒、腰髀作痛、痰注成漏等症。各类病机相互关联：肝旺可乘脾，脾虚生湿痰，湿滞又碍气血，形成恶性循环。治疗宜和荣卫、化痰湿、平肝木，兼顾虚实。", "c": [{"name": "主肝旺", "desc": "弦脉为肝旺之象，原文'弦主肝旺'，关部候肝，故关脉弦主肝气大旺，气机失调，可见胸腹不舒、腰髀作痛等症。"}], "n": {"主肝旺": 1}, "a": {"18218": "主肝旺"}, "t": 1, "np": 0}, "c:数+紧+实": {"o": "紧实数脉在此段中并非寻常数实之脉，而是与屋漏、雀啄、弹石、解索、虾游、鱼翔等怪脉并列，总属无胃气柔和之象的死脉范畴。其总病机为胃气败绝、脏真外泄，脉来坚急数疾而绝止复顿，或散乱无根，反映脏腑精气衰败、阴阳离决。三类病机相互关联：胃气败绝是根本，脏真外泄是表现，脉病形不病则提示危候潜藏。三者从不同角度共同说明紧实数怪脉主危重死候，而非一般实热或紧实之病。", "c": [{"name": "主胃气败绝", "desc": "紧实数脉见屋漏、雀啄、弹石、解索等怪脉，原文谓‘无胃气柔和之象’，脉来数疾而绝止复顿来，或辟辟急、动数散乱，皆脏气衰败、胃气将绝之征，故主危候。"}], "n": {"主胃气败绝": 1}, "a": {"21823": "主胃气败绝"}, "t": 1, "np": 0}, "c:数+浮+软": {"o": "数浮软脉总起来主虚热与正虚邪恋之证。其核心病机为阴亏火旺，数脉主热，浮软无力则非实火，乃肾阴亏损、水不制火之虚热。由此衍生三类相关病机：一是暑热挟虚，浮弦软数并见，暑热外扰而真阴内亏；二是疟邪未清，暑热化疟，邪恋伤阴；三是风邪上攻，浮软小数，高年气血不足而风邪留恋，郁而化热。诸类之间以‘正虚’为共同基础：或阴虚，或气血不足；以‘邪恋’为共同标象：或暑热，或疟邪，或风邪。虚为本，邪为标，虚热为变，故脉象虽数而浮软无力，总属不足中有邪滞之候。", "c": [{"name": "主阴虚火旺", "desc": "脉数浮软无力，数主热，浮软无力则非实火，乃肾阴亏损、水不制火，虚火上炎所致。原文阴虚喉痹见内热口渴、唇红颊赤，但尺脉无神、六脉数而浮软，正说明热为虚热，病本阴亏。"}], "n": {"主阴虚火旺": 1}, "a": {"23502": "主阴虚火旺"}, "t": 1, "np": 0}, "c:数+迟+疾": {"o": "数迟疾脉在《三部九候论》中主要反映脉律败乱与形脉相失，总属危重死候。其核心病机为五脏已败、阴阳离绝：脉来乍数乍疏乍迟乍疾，是脉气败乱、阴阳不相维系的征象；形盛脉细或形瘦脉大，是形脉不称、气外浮无根；九候相失、上下左右不可数，是阴阳离绝。诸类之间相互关联，脉律败乱为根本，形脉相失与阴阳离绝为具体表现，最终皆归于死候。故数迟疾脉总主脏气衰败、阴阳离绝之危候。", "c": [{"name": "主死候", "desc": "原文多次直言死候，如形瘦脉大胸中多气者死、三部九候皆相失者死、上下左右相失不可数者死、中部之候相减者死、目内陷者死、脱肉身不去者死。数迟疾脉见乍数乍疏乍迟乍疾，为脉律败乱，标志五脏已败，故主死。"}], "n": {"主死候": 1}, "a": {"23710": "主死候"}, "t": 1, "np": 0}, "pc:尺+大+微+弱": {"o": "尺·大微弱脉总以虚为纲，所主病机不离阴虚、气血亏虚与津伤三类。原文以'尺脉大或无力而渴'示肾阴亏虚、虚火浮越；以'脉大无力或微弱而渴'示气血两虚、脉道不充；又因气虚不能生津、脓血大泄而渴，知此脉亦主津液耗伤。三类之间相互关联：阴虚可致火旺灼津，气血虚则津液化生不足，久病脓血更直接耗伤气血津液，故同一渴症，脉实者泻、脉虚者补，凭脉定虚实。此脉总属虚候，治宜滋阴降火、补益气血、生津止渴，忌用苦寒攻泻。", "c": [{"name": "主阴虚火旺", "desc": "原文'尺脉大或无力而渴者，宜滋阴降火'，尺脉大而无力为阴亏于下、虚火浮越之象，故主肾阴不足、虚火内生，治当滋阴降火。"}], "n": {"主阴虚火旺": 1}, "a": {"23978": "主阴虚火旺"}, "t": 1, "np": 0}, "c:数+微+紧": {"o": "微紧数脉总起来主风热邪聚、正气不足之候，常见于肺痿、肺痈等病。数主热，紧主邪聚血壅，微主正虚。三者相合，提示风热之邪内侵，气血壅聚，而正气已伤。若脉数而虚，为津液重亡、肺叶焦枯之肺痿；数而实，为风热蕴结、气血稽留之肺痈。微紧而数者，邪聚未甚，脓未成；紧甚而数者，邪壅血腐，脓已成。诸类病机相互关联：热为邪之性，紧为邪之聚，微为正气之衰，成脓为邪热壅聚之果。总以邪正相争、热壅血聚为要。", "c": [{"name": "主热", "desc": "数脉主热，原文明言“数主热”，风热相搏，热伤血脉，故脉数。热邪内蕴，气血运行加速，脉来急数，为热盛之征。"}], "n": {"主热": 1}, "a": {"24012": "主热"}, "t": 1, "np": 0}, "c:细+滑+浮": {"o": "浮细滑脉在古籍中仅见一段论述，其核心主病为“伤饮”。浮脉主邪在表或在上，提示饮邪初伤、病位偏浅；细脉主饮湿内蕴、脉道受抑；滑脉主饮邪流溢、气血尚充。三象合参，反映饮邪初伤人体，尚未深入沉结，故脉象仍带浮滑。此脉所主病机较为单一，以饮邪伤中为主，未见其他病机类别。临证见此脉，当结合症状辨明饮邪所在部位及轻重，以温化或渗利为治。", "c": [{"name": "主饮", "desc": "原文直断“伤饮”，浮主饮邪在表或上，细滑主饮湿内蕴。浮细滑并见，说明饮邪初伤，未至沉结，脉象尚带浮滑，与暴饮伤中之病机相应，故以脉测证，主伤饮。"}], "n": {"主饮": 1}, "a": {"25340": "主饮"}, "t": 1, "np": 0}, "pc:六+浮+洪": {"o": "浮洪脉总以浮、洪二象相合为纲，浮主邪在表或气逆于上，洪主热盛或火盛阳亢，故总起来主热邪为患，但具体病机有表里虚实之异。实热者，或热盛于气分，或热毒壅盛，或湿热内伏，或表里俱热，脉多浮洪有力；虚热者，气阴两虚、阳浮不摄，脉虽浮洪而重按空软。此外，浮洪亦主气逆火炎、肝火灼金之喘哮。各证之间，以热盛为核心，表热、湿热、热毒为实热之不同部位与性质，虚阳浮越为虚热之变，气逆火炎为火热上冲之候，临证须结合兼脉及证候，辨其虚实表里。", "c": [{"name": "主热盛", "desc": "浮洪脉以洪为热盛之象，浮为热邪外扬。原文多段见‘洪主热盛’‘洪主火盛阳亢’，如气逆喘哮、火灼乘金、骨蒸发热、肤如火燎等，皆因热邪炽盛，充斥气分，鼓动脉道而现浮洪。"}, {"name": "主表热", "desc": "浮主邪在表，洪主热盛，浮洪并见提示热邪在肌表。原文‘浮主邪在表’‘热在肌表、卫气不固’，如漏风案头痛发热、自汗盗汗，脉浮洪而重按豁然，说明热未深结，邪尚在表。"}, {"name": "主湿热", "desc": "浮洪脉可见于湿热内伏、邪阻中焦。原文‘浮主邪未全退，洪主热盛气分’，身热退而脉仍浮洪，舌根腻、便溏色黑、小便短赤，为余热未清、湿滞未化，湿热伏邪阻于中宫。"}, {"name": "主虚阳浮越", "desc": "浮洪脉亦可见于气阴两虚、阳浮不摄之证。原文‘阳旺于阴，阴不敛阳，虚火浮越’，下消症六脉浮洪而右寸关空软、左尺衰微，说明虚火浮越于外，非实热可比。"}, {"name": "主气逆火炎", "desc": "浮洪脉可主肝火挟肺气上逆、火热灼金。原文‘浮主气逆于上，洪主火盛阳亢’，气逆喘哮、言语不续、舌燥津亏，肝经独旺，火炎上喘，浮洪并见正示气逆火炎之机。"}], "n": {"主热盛": 2, "主表热": 2, "主湿热": 1, "主虚阳浮越": 1, "主气逆火炎": 1}, "a": {"1871": "主气逆火炎", "1892": "主湿热", "1893": "主表热", "3294": "主表热", "17459": "__np", "18264": "主虚阳浮越", "19940": "主热盛", "27121": "主热盛"}, "t": 8, "np": 1}, "pc:右+大+缓": {"o": "右·大缓脉总起来主虚与邪壅两类病机，而以虚为多。大脉主劳、主虚，缓脉主脾虚湿滞，故右大缓脉首先反映劳倦伤脾、中气不足，进而气血两虚、脾胃大虚；若缓大无力、重按皆无，则为大虚之候。另一方面，大缓亦可见于胃阴伤而气机弛纵，或湿热痰火壅阻气分，此时大示邪壅、缓为湿象，弦大缓相合则湿、热、痰、火交结。此外，右脉大缓见于气口，又主内伤饮食、劳役不节之不足病。各类之间，虚证以脾胃气虚、气血两虚为核心，实证以湿热痰火壅阻为要，胃阴伤则属虚中夹热，内伤不足则统括劳倦饮食所伤，总不离右手气口主内伤、主脾胃之定位。", "c": [{"name": "主劳倦脾虚", "desc": "右大缓脉主劳倦伤脾、中气不足。原文见右大而缓，左小数促，伴面浮足肿、呼吸喘、食纳不运，乃劳役饥饱嗔怒后病加，脾胃衰而营卫失度。仲景谓“男子脉大为劳”，大缓为劳倦伤脾、中气不足之象，数促为虚阳内扰。"}, {"name": "主气血大虚", "desc": "右大缓散脉主气虚、脾胃虚、气血两虚。原文见左脉散大而缓，右脉缓大不及左，重按皆无力，头目昏眩、手足无力、吐痰相续，乃大虚证。散大主气虚外散，缓大无力主脾胃大虚，二者相合则气血俱虚，治以大补气血。"}, {"name": "主胃阴伤", "desc": "右缓大脉主胃中津液为辛散温燥所伤，热焰蒸迫心营肺卫。原文见面垢减而痰嗽不爽、神呆喘急耳聋、清阳阻痹、九窍不利。缓大非实，乃胃阴伤而气机弛纵，左弱示营血不足，治当清养胃阴肺气。"}, {"name": "主内伤不足", "desc": "右大缓脉见于右手气口，主内伤饮食及劳役不节，为不足之病。原文以人迎气口辨内外伤，气口脉大于人迎为内伤，内伤饮食则右寸气口脉大而数、急大而缓，皆不足之病，必见于右手。"}], "n": {"主劳倦脾虚": 2, "主气血大虚": 1, "主胃阴伤": 2, "主内伤不足": 2}, "a": {"1135": "主劳倦脾虚", "1300": "主胃阴伤", "3562": "主气血大虚", "4509": "主劳倦脾虚", "4553": "主胃阴伤", "18621": "主内伤不足", "19322": "主内伤不足"}, "t": 7, "np": 0}, "pc:关+滑+沉": {"o": "关脉沉滑总属里实之候，以右关候脾胃为核心，主痰、食、气、热等实邪内结中焦。沉主里，滑主痰主食，故痰浊内蕴、食积内停、气滞食凝、热结里实皆可见此脉，四者常相兼为患，只是兼脉与偏重不同。若兼弦象，则涉肝郁，成肝胃不和；若兼火风之象，则痰火风扰，上蒙清窍。诸类之间，以痰食气滞为基础，郁久化热则成热结，波及于肝则肝胃失调，引动风火则上扰清窍。总以实邪壅滞、气机不畅为病机关键，虚证少见。", "c": [{"name": "主食积内停", "desc": "滑主宿食，沉主里滞，右关沉滑为食积内停之征。原文明言“右关沉滑，乃是食积”，并据兼脉分寒热；关脉沉滑，为气食交阻，少腹痛块；右关沉滑，主气食相凝。食积中焦，胃气壅滞，故见呕吐、腹痛、痞满。"}, {"name": "主热结里实", "desc": "沉滑有力或兼数，示实热与有形积滞内结。原文关脉沉滑，为温毒壅遏中焦，热毒与积滞相结，故用下法；滑数主内有热结；沉数主热积。热与食痰相搏，结于胃肠，故见烦躁、便秘、腹满痛等里实证。"}, {"name": "主气滞食凝", "desc": "沉滑主里实，气食交阻亦见关脉沉滑。原文关脉沉滑，为冒风兼气食交阻，少腹痛块；右关沉滑，主气食相凝；右关沉滑，为胃不和、饮食停积。气机壅滞，食积内停，故见腹痛、呕吐、胀满。"}, {"name": "主肝胃不和", "desc": "右关沉滑主胃中痰食不化，左关小弦主肝气郁滞，两关合参则肝胃不和。原文右关沉滑，左关小弦，断为胃不和、肝不疏，致食入即吐。肝郁犯胃，胃气上逆，故见呕吐、嗳噫。"}, {"name": "主风火痰扰", "desc": "沉滑主痰，兼见火风之象，则痰火风邪上扰。原文右关沉滑有力，舌苔白腻中心焦黄，断为浊痰弥漫、心窍闭阻，而火风鼓旋之势尚炽，症见口眼㖞斜、舌强言蹇、手足不遂。痰火内结，风邪煽动，故见中风之候。"}, {"name": "主内伤饮食", "desc": "气口脉大而数、急大涩数或沉滑，主饮食不节、劳役所伤，脾胃内伤不足之证，与外伤人迎脉大相对。"}], "n": {"主食积内停": 1, "主热结里实": 1, "主气滞食凝": 2, "主肝胃不和": 1, "主风火痰扰": 1, "主内伤饮食": 1}, "a": {"7236": "主风火痰扰", "12056": "主热结里实", "15839": "主气滞食凝", "15872": "主肝胃不和", "19322": "主内伤饮食", "24629": "主气滞食凝", "25037": "主食积内停"}, "t": 7, "np": 0}, "pc:左+细+滑": {"o": "左细滑脉总起来主正虚邪实之候，以阴血不足为本，痰湿内蕴为标。细脉主血少、心肾亏虚，滑脉主痰湿、妊娠。四段原文中，或见阴血不足兼痰浊内蕴，或见营虚与胎孕并见，或见心肾虚弱兼暑湿痰火，或泛论滑脉多血少气。各类病机相互关联：血虚与痰湿常并存，形成虚实夹杂；滑脉既可主痰湿，又可主妊娠，需结合兼症鉴别。左细滑脉的核心在于正虚（血少、心肾不足）与邪实（痰湿、暑湿）交织，临证当细辨虚实主次。", "c": [{"name": "主血虚", "desc": "细脉主阴血不足，左脉候心肝肾，左细为营血亏虚、心肾不足之象。原文如'左细滑'案中'细为营血不足''左细为心肾不足'，均以细脉示正虚血少，故左细滑脉可主血虚。"}, {"name": "主正虚邪实", "desc": "细滑并见，细为血少正虚，滑为痰湿邪实，形成正虚邪实之候。原文'细滑并见，正虚邪实''脉象反映正虚与痰浊'，说明左细滑脉常示虚实夹杂，如心肾虚弱兼暑湿痰火。"}, {"name": "主妊娠", "desc": "滑脉亦主妊娠，左细右滑颇有，经闭三月，药下不至，滑象提示胎孕可能。原文'右滑颇有提示或有胎孕之象'，虽左细示营虚，但滑脉为妊娠之征，故左细滑脉可主妊娠。"}], "n": {"主血虚": 1, "主正虚邪实": 2, "主妊娠": 1}, "a": {"256": "主正虚邪实", "9951": "主妊娠", "11324": "主正虚邪实", "21801": "主血虚"}, "t": 4, "np": 0}, "pc:左+滑+浮": {"o": "左·滑浮脉总属痰、热、风、湿为患，以痰热壅肺为核心，兼涉表风与血分。浮主表主风，滑主痰主湿，左候肝与表，故其病机多端。四类中，痰热壅肺与风邪在表常相兼为病，风痰上扰肺络；血多气少为滑脉本象，示血实气壅；热盛动风则由浮滑兼数疾而化，热势急迫，痰热内扰。诸类相互关联：风邪外袭为病之始，痰热内蕴为病之枢，血多气少为体质基础，热盛动风为病之变。总以痰热壅肺、风痰上扰为主，兼及血分壅实与热盛动风之虞。", "c": [{"name": "主痰热壅肺", "desc": "左脉浮滑，浮主表主风，滑主痰主湿，合而主痰热壅肺。原文见咳甚痰脓带血、不能伏枕，断为肺痈，以清肺泻肺取效；又有风邪未清、咳逆舌薄白，治以止嗽化痰疏风。皆因痰热或风痰阻于肺络，肺气上逆所致。"}, {"name": "主风邪在表", "desc": "浮脉主表主风，滑脉主痰，左脉浮滑提示风邪未清、痰浊内蕴。原文见头疼较差、舌薄白、咳逆，为风痰上扰之征。风邪在表，痰阻肺络，故脉浮滑并见，治宜疏风化痰，使表邪与痰浊并解。"}, {"name": "主血多气少", "desc": "滑脉本象往来流利，主血实气壅。原文直言“脉滑者，多血少气”，左脉浮滑亦含此义。血多气少则气分相对不足，血中壅实，脉道流利而滑，浮则示病位偏表或在上，故见血多气少之病机。"}], "n": {"主痰热壅肺": 2, "主风邪在表": 1, "主血多气少": 1}, "a": {"4115": "主痰热壅肺", "15178": "主痰热壅肺", "16733": "主风邪在表", "21801": "主血多气少"}, "t": 4, "np": 0}, "pc:右+沉+弱": {"o": "右·沉弱脉总属虚候，以正气不足为核心，涵盖气虚、血虚、阳虚、脾虚肝侮及下虚阴伤等病机。沉弱无力，右手主气，故首主气虚；气虚日久，阳失温煦，则为阳虚；血虚脉道不充，亦见沉弱；脾虚气弱，肝木乘之，则见脾虚肝侮；沉取极弱，又主下焦阴伤。诸类相互关联：气虚则阳弱，阳弱则运化无力，气血生化不足；血虚则脉道不充，气亦随之而衰；脾虚则肝易侮之；阴伤则沉取更弱。总以虚为本，或兼木乘，或兼阴亏，然不离正气亏虚之要。", "c": [{"name": "主血虚", "desc": "沉弱脉按之不足，阴血亏虚，脉道不充。案15082右脉浮小无力、左脉沉弱无力，为脾虚血少、肠道失润；案15157左脉沉弱为血虚气陷。弱脉主营血不足，故主血虚。"}, {"name": "主脾虚肝侮", "desc": "右脉沉弱主脾气虚，左脉滑大或弦为肝风、肝郁之象，土虚则木乘。案4143右脉沉弱、左脉滑大，断为气虚肝侮，手足瘛疭；案15157右脉浮虚颇弦，为土虚木乘。故主脾虚肝侮之病机。"}, {"name": "主下虚阴伤", "desc": "沉取极弱，候里候阴，弱为不足，示下焦阴液亏虚。案5094六脉沉取极弱，断为下虚阴不足，于辛凉方中加护阴法。沉弱不独主气，亦主阴亏于下，故主下虚阴伤。"}], "n": {"主血虚": 1, "主脾虚肝侮": 2, "主下虚阴伤": 1}, "a": {"4143": "主脾虚肝侮", "5094": "主下虚阴伤", "15082": "主血虚", "15157": "主脾虚肝侮"}, "t": 4, "np": 0}, "pc:右+涩+濡": {"o": "右·涩濡脉总属脾虚湿滞、气血不足、土虚木乘之候。濡为脾虚湿停，涩为营血亏少、气机不畅，二者合见，反映脾胃虚弱、湿滞血少、气机升降失常的复杂病机。其核心在脾：脾阳不运则湿滞内生（濡），化源不足则营血亏虚（涩），土虚则木乘（弦）。四类病机中，脾虚湿滞为根本，气血亏虚为脾虚化源不足所致，土虚木乘为脾虚肝旺之变，痰郁气逆为湿滞生痰、肺失治节之果。四者相互关联，总以脾虚为中心，涉及气血、肝肺，故临床可见咳呛、下痢、脘痛、胀满、纳减、神倦等症，治宜脾肺兼治、培补温润、佐以辛甘。", "c": [{"name": "主脾虚湿滞", "desc": "右脉濡涩，濡为脾土虚弱、湿邪内停，涩为气机不畅、湿滞血少。原文如案10'濡涩为脾阳已亏、暑湿未清，运化失司'，案13'土弱则濡'，案5'胃阳虚而阴亦耗'，均示脾虚运化失司，湿滞内生，故主脾虚湿滞。"}, {"name": "主土虚木乘", "desc": "右脉濡涩而左虚弦，濡为脾土虚弱，涩为营血亏少，虚弦为肝木偏亢。原文案13'木亢侮土'，案5'土受木克'，案10'肝脾不和'，皆示土虚木乘、肝脾不调，故主土虚木乘。"}, {"name": "主痰郁气逆", "desc": "濡涩为脾虚湿滞，湿聚成痰，气机不畅；右脉候肺，肺虚治节不行，痰郁气逆。原文案12456'气虚痰郁，肺为娇脏不耐邪侵'，'卧时喉中有水鸡声'，皆示痰郁气逆之候，故主痰郁气逆。"}], "n": {"主脾虚湿滞": 1, "主土虚木乘": 2, "主痰郁气逆": 1}, "a": {"6605": "主脾虚湿滞", "6637": "主土虚木乘", "6996": "主土虚木乘", "12456": "主痰郁气逆"}, "t": 4, "np": 0}, "pc:关+数+洪": {"o": "关·数洪脉总起来主阳热亢盛之证。洪为热盛，数为火急，故其核心病机为热盛，可燔灼三焦，分候脏腑则见肝胆、胃、肺、心、肾等火证。热盛进一步可致燥火伤津，见于三消；或灼伤阴血，形成肝火血燥；在瘴疟中，洪数主瘴热，兼弦紧主寒热交争，浮紧浮缓主表证，按之不实主阳浮阴闭，沉微弱主虚寒。各类之间以热盛为本，脏腑火、燥伤津、肝火血燥、瘴疟表证为热盛之不同表现或兼夹，虚实寒热转化亦可见。", "c": [{"name": "主热盛", "desc": "洪为热盛，数为火急，关脉数洪直接反映阳热亢盛。原文如温毒壅遏上焦见寸脉洪数，内火喘逆脉多洪数，燥火三消关脉洪数，皆以洪数主热盛，热势急迫，燔灼三焦。"}, {"name": "主脏腑火", "desc": "数洪脉分候脏腑，各脏火逆上干。左关数主肝胆热，右关洪数主胃火，右寸洪数主肺火，左寸洪数主心火，两尺洪数主肾火。洪数为火盛热炽，故各脏腑火证皆可见关部数洪。"}, {"name": "主燥伤津", "desc": "燥火三消之脉，关脉洪数主燥伤中焦，燥伤气则脉大数，伤血则细数。洪数示燥火亢盛，耗伤津液，故主燥火伤津之病机，见于三消等证。"}], "n": {"主热盛": 1, "主脏腑火": 2, "主燥伤津": 1}, "a": {"12056": "主热盛", "24814": "主脏腑火", "24866": "主脏腑火", "24908": "主燥伤津"}, "t": 4, "np": 0}, "pc:左+滑+实": {"o": "左·滑实脉总属实证、热证，以实热壅盛、痰气内阻为核心病机。其具体所主包括痰热内壅、肝胃郁热、痰凝气滞、痰饮食积四类。痰热内壅多因外感稽留，热灼津液成痰，痰热胶结于肺胃；肝胃郁热则由风束或气郁化火，热壅于胃与肝胆；痰凝气滞侧重痰与气互结，阻滞经络；痰饮食积则因中焦壅滞，痰饮与食积相合。四类均以滑实脉为共同特征，滑主痰湿，实主邪盛，故脉象反映邪实壅滞之象。各类之间相互关联：实热可炼液为痰，痰凝又可加重气滞，食积亦能化热生痰，总以邪实为要，治当清热化痰、行气导滞。", "c": [{"name": "主痰热内壅", "desc": "滑实脉主痰热壅盛。原文如右脉滑而实，舌黄苔满布，大便燥，咳嗽吐痰腥臭，为外感稽留肺胃，久而生炎，痰热内壅之象。滑主痰，实主邪盛，故痰热胶结，壅滞肺胃。"}, {"name": "主肝胃郁热", "desc": "滑实脉见于右脉，主胃中郁热；左脉弦硬，主肝胆郁热。原文谓右脉滑而实者，外为风束胃中亦浸生热也，左脉弦硬者，肝胆有郁热也。滑实反映热邪内郁，气血壅滞。"}, {"name": "主痰凝气滞", "desc": "滑实脉主痰凝气滞。原文右脉滑实，痰凝气滞，见于口噤不语。滑主痰，实主气机壅实，痰气交阻，经络不通，故见口噤。此与单纯热盛不同，侧重痰气凝结。"}, {"name": "主痰饮食积", "desc": "滑实脉主痰饮食积。原文右脉滑实，痰饮食积，见于遗尿。滑实脉示中焦壅滞，痰饮与食积内停，气机不畅，影响膀胱约束。此与痰热内壅相近，但侧重食积，病位在肠胃。"}], "n": {"主痰热内壅": 1, "主肝胃郁热": 1, "主痰凝气滞": 1, "主痰饮食积": 1}, "a": {"19541": "主痰热内壅", "20527": "主肝胃郁热", "24628": "主痰凝气滞", "24639": "主痰饮食积"}, "t": 4, "np": 0}, "pc:两+疾+促": {"o": "两脉促疾，总属邪火燎原、阴津消涸之危候。促为阳盛搏急，疾为热极躁动，二脉相合，反映热邪亢盛、阴液耗伤之病机。热盛则脉促疾，热盛劫津则阴伤，阴伤筋脉失养则风动，风动神昏、手指牵引，诸症丛生。虽大便通、病热略减，然脉仍促疾无伦，是邪火未衰而阴津难复，故脉象不减则险象未除，预后堪忧。四类病机以热盛为始，阴伤为继，风动为变，险候为果，层层相因，总归邪火与阴伤之争。", "c": [{"name": "主险候", "desc": "促疾无伦，脉不与症俱减，虽便通病减，脉仍促疾，示邪火未衰而阴津难复。原文'仍属险象''恐其复剧'，脉象不减则险象未除，故主险候。"}], "n": {"主险候": 3}, "a": {"10836": "主险候", "13551": "主险候", "14632": "主险候"}, "t": 3, "np": 0}, "pc:六+濡+软": {"o": "濡软脉总起来主虚证与湿证，以气血不足、脾虚湿困为本，并可兼见肝旺乘脾、痰饮内伏等标实之象。从所收两段原文看，濡软脉的核心病机是正气亏虚，尤其是气血不足和脾虚，导致脉道松弛软弱；同时，脾虚运化失职，湿邪内困，亦使脉现濡软。若兼见沉弦，则提示肝旺乘脾、痰饮内伏，形成本虚标实之证。各病机类别之间相互关联：气血不足与脾虚湿困常并存，脾虚湿困又可引动肝木乘脾，进而导致痰饮内伏。因此，濡软脉所主病机以虚为基础，湿、痰、肝旺为标，临证需结合兼脉及部位综合判断。", "c": [{"name": "主脾虚湿困", "desc": "濡软脉象主脾虚湿困。原文言'六脉濡软，沉候俱弦，右关尤甚'，并指出'濡软主脾虚湿困'。脾虚运化失职，湿邪内困，脉道松弛，故见濡软。右关候脾，右关尤甚，更说明脾虚湿困为病机核心。"}], "n": {"主脾虚湿困": 2}, "a": {"7607": "主脾虚湿困", "24641": "主脾虚湿困"}, "t": 2, "np": 0}, "c:浮+和": {"o": "浮和脉总起来主表邪渐解而余邪未净，或正虚邪恋、水饮内停之证。其脉象浮而较和，说明外浮之势已缓，但浮象仍在，提示病位偏表或气机浮越。从所涉段落看，浮和脉可因表邪渐解而见，此时邪气虽减而未尽；亦可因水饮内停、气机不畅而兼弦象，反映湿无出路；还可因久病正虚、宿瘕不化而见浮搏较和，属正虚邪恋。三类病机相互关联：表邪渐解是前提，水饮内停是兼邪，正虚邪恋是转归，总以邪减正伤、气机未复为共同特点。", "c": [{"name": "主表邪渐解", "desc": "脉浮已和或浮搏较和，提示表邪渐解，浮越之气稍敛，搏指之势渐缓。如原文“脉浮已和”“浮搏较和”，说明外邪已减，但余邪未尽，故仍见浮象。"}], "n": {"主表邪渐解": 2}, "a": {"8972": "主表邪渐解", "10527": "主表邪渐解"}, "t": 2, "np": 0}, "pc:寸+弦+紧": {"o": "寸·弦紧脉总起来主风寒外客、疼痛、寒积内结及津亏内伤。弦主风、主痛，紧主寒，寸关见之，首为风寒客于肌肤，故见蒸蒸发热、盗汗；寒性收引，气血不通则痛；若沉紧，则寒邪内结，心下寒痛有积；若病久不愈，风寒化热伤津，则津液渐亏，转为内伤黄瘦。四类病机以风寒外袭为始，进而可致疼痛、寒积，久则伤津成内伤，其间存在由表入里、由实转虚的演变关系。", "c": [{"name": "主风寒表证", "desc": "弦主风、紧主寒，寸关见弦紧，为风寒客于肌肤，故见日晡蒸蒸发热、盗汗达旦等症。原文明言“风寒客于肌肤”，且久则津液渐亏，从外感转内伤，说明弦紧脉首先反映外感风寒之邪在表。"}], "n": {"主风寒表证": 2}, "a": {"10413": "主风寒表证", "21803": "主风寒表证"}, "t": 2, "np": 0}, "pc:寸+大+实": {"o": "寸·大实脉总属邪热亢盛、实火内壅之象。其脉形大而有力，来盛去盛，为太过之脉，主病在外。所主病机以实热为核心，可具体分属胃火、肺热及火刑金等。右关实大主胃火刑金，右寸洪数主肺热，尺数大主肾火，左关弦数主肝火，左寸洪数主心火，诸部实大洪数皆火热亢盛之征。大实脉与洪数弦等并见，说明火邪充斥三焦，脏腑相移，尤以肺胃为多。实大非虚，乃邪气盛而正气未衰，故治当清泻实火。各类之间以实热为共同基础，因火邪所犯脏腑不同而有所侧重，然总不离火盛壅实之机。", "c": [{"name": "主实热", "desc": "大实脉主邪热壅盛。原文见关脉实大，注为‘实大为邪热壅盛，主胃火刑金’；又寸脉大实与洪数并见，属火热亢盛之象。实大有力，为邪气盛而正气未衰，热结于内，故主实热之证。"}], "n": {"主实热": 2}, "a": {"19361": "主实热", "24866": "主实热"}, "t": 2, "np": 0}, "pc:左+乱+碎": {"o": "左·乱碎脉总起来主肝肾同病，以肝风上冒为重心，肾阴亏虚为根源。其脉象碎乱搏指，脉道失其常度而搏指不宁，是风阳扰动、阴不涵阳之征。原文明言“肝风上冒”，又谓“乙癸同源，肾肝同病”，且以肝为重、肾次之，说明病机核心在肝风内动、上扰清窍，而肾阴亏虚则为其发病基础。三类病机相互关联：肾阴亏虚则肝木失涵，肝风上冒又进一步耗伤肾阴，形成肝肾同病之局。故本脉所主，总以肝风上冒为标，肾阴亏虚为本，二者相合而见碎乱搏指之象。", "c": [{"name": "主肝风上冒", "desc": "原文明言“肝风上冒”，左尺脉碎乱搏指，碎乱者脉道失其常度、搏指不宁，为风阳扰动之象。风性主动，故脉见碎乱搏指不宁，主肝风内动，上冒清窍。"}], "n": {"主肝风上冒": 1}, "a": {"28": "主肝风上冒"}, "t": 1, "np": 0}, "pc:右+虚+动": {"o": "右·虚动脉此段所主，总为虚而阳亢、风热上扰之候。其脉右大，右部候气，大则阳气亢盛，然此大非实热壅盛之洪大，而是虚阳浮越、化风上逆之象，故原文既言“热升风动”，又强调“奇脉虚风阳动”“虚风内动”。可见其病机核心是虚与风热并存：正虚于下，阳亢化风于上，风热相煽，上扰清窍，发为郁冒昏厥。两类病机一为热升风动之标象，一为虚风内动之本质，标本相因，不可分割。临床见此脉，当辨其大而无力，治宜凉肝息风兼顾其虚，如羚羊角散之类，不可纯用苦寒直折。", "c": [{"name": "主热升风动", "desc": "原文谓“脉右大。热升风动。郁冒为厥”，右脉候气，大则阳亢化风，风热上扰清窍，故见郁冒昏厥。此脉大非实热壅盛，乃虚而阳亢化风之象，热与风相合上逆为病。"}], "n": {"主热升风动": 1}, "a": {"1586": "主热升风动"}, "t": 1, "np": 0}, "pc:六+微+洪": {"o": "微洪脉总主热证，尤以肺经气分热为核心。微为热势未盛，洪为热邪鼓动，二者相合，提示热在气分而尚未炽盛。原文以骨蒸发热、肤如火燎、吐痰烦渴、烦躁引饮昼盛为据，李时珍用一味黄芩泻肺经气分火而愈，说明微洪脉所主之热，病位在肺，病性属气分。两类病机相互关联：肺热是具体病位，气分热是病性层次，肺热气分热实为一体。微洪脉既非洪大之实热，亦非微细之虚热，而是热邪初盛、鼓动血脉之象，故其主病机可归纳为肺经气分热，热势未极。", "c": [{"name": "主肺热", "desc": "原文载骨蒸发热、肤如火燎、吐痰烦渴，六脉微洪。洪为热盛鼓动，微示热势未极，李时珍以黄芩泻肺经气分火而愈，故微洪脉主肺经气分热，热邪壅肺，鼓动血脉。"}], "n": {"主肺热": 1}, "a": {"3605": "主肺热"}, "t": 1, "np": 0}, "c:微+和": {"o": "微和脉总以和缓之象为特征，核心在于反映胃气盛衰与邪正进退。其主病机可归纳为三类：一为胃气渐复，见于病后脉转微和，示胃气来复、病势向愈；二为邪退正虚，见于急疾歇止脉后脉息微和，虽邪去而气血已伤，神思恍惚；三为邪恋正复，见于弦微和脉，弦为邪郁未清，微和为胃气尚存，故疟邪未尽而胃气渐复。三类之间以胃气为枢机：胃气复则病退，胃气弱则邪恋，正虚与邪恋常相兼见。微和脉本身非独立病脉，而是判断预后转归的关键指征，由弦急转和缓为佳，由和缓转弦急为逆。", "c": [{"name": "主胃气渐复", "desc": "微和脉以和缓为特征，代表胃气尚存或渐复。原文中下异胎后脉息微和，示邪去正复，胃气来复，病势向愈。微和缓脉总述亦强调和缓为胃气之象，由弦急转和缓为胃气来复。"}], "n": {"主胃气渐复": 1}, "a": {"4060": "主胃气渐复"}, "t": 1, "np": 0}, "pc:六+涩+小": {"o": "涩小脉总起来主肝旺脾虚、痰饮内伏、营血不畅之证。其脉象以涩为主，涩为营血不畅、气机郁滞；小则脉道收引，示邪阻脉道。兼见濡软、沉弦等，反映脾虚湿困、肝木乘土、痰饮内停。各病机相互关联：肝气郁滞则木横克土，脾虚不运则湿浊内生，湿聚成痰成饮，痰饮阻滞又加重气滞血涩。故涩小脉所主，以肝脾不调为本，痰饮、湿浊、血涩为标，形成虚实夹杂、气血痰湿互结之候。", "c": [{"name": "主肝旺乘土", "desc": "脉见左尺小涩，兼右关弦甚，乃肝木勃动、乘于土位之象。原文谓“肝木纵横，挟内伏之痰饮，乘于土位”，故右半胸腹尤甚、中宫窒塞。涩为营血不畅，小则脉道收引，反映肝气郁滞、木横克土之病机。"}], "n": {"主肝旺乘土": 1}, "a": {"7607": "主肝旺乘土"}, "t": 1, "np": 0}, "pc:左+滑+微": {"o": "左·滑微脉总起来主痰湿中阻、木亢升浮之病机。右脉微滑反映胃有湿痰、胃欠通降；左关独弦反映风木偏亢。二者相合，形成胃降不及、胆气不能下行，肝脾升有余而胆胃降不足的格局，遂致眩晕。各类病机之间具有因果关联：湿痰中阻为始动因素，导致胃失和降；胃降不及又使胆气不能下行，进而肝木偏亢、木燥生风；风痰上扰清窍，则发为眩晕。故滑微脉所主以痰湿为基础，以木亢为标象，以眩晕为常见症候，体现了痰、风、逆三者交织的病理特点。", "c": [{"name": "主湿痰", "desc": "右脉微滑，为胃有湿痰。滑脉主痰湿，微则示痰湿不盛或兼虚。原文明言“右脉微滑，为胃有湿痰，胃欠通降”，故滑微脉主痰湿中阻，胃失和降。"}], "n": {"主湿痰": 1}, "a": {"8136": "主湿痰"}, "t": 1, "np": 0}, "c:微+芤": {"o": "微芤脉总起来主失血，其病机核心为阳气衰而阴血脱。微脉主阳气虚衰，鼓动无力；芤脉主阴血脱失，脉道空虚。二者相合，提示血去络空、气血两伤之虚象，非实邪为患。因血脱则气亦衰，阳气不足则脉微，阴血亏耗则脉芤，故临床多见于失血之后，并伴络脉失养之隐痛。诸类病机以失血为总纲，阳气衰与阴血脱为失血之因果，络脉失养为失血之局部表现，总属虚证。", "c": [{"name": "主失血", "desc": "原文明言“脉微而芤，失血之象也”，芤为阴血脱，微为阳气衰，血去络空，故主失血。"}], "n": {"主失血": 1}, "a": {"8539": "主失血"}, "t": 1, "np": 0}, "c:细+芤": {"o": "芤细脉总起来主失血与营阴亏虚，其核心病机为‘血去络伤、阴血不足’。芤脉中空，主失血伤络；细脉如线，主营阴亏少。二者相合，多见于崩漏、失血之后，或老年营阴不摄、内络已损之证。原文明确以‘芤主失血’‘细主营阴亏少’并提，且指出‘向有失血，内络已损’，说明失血与阴亏并存。在此基础上，若逢炎夏暑热，则外热更耗营阴，可兼见虚热之象。故芤细脉所主，以失血、营阴亏虚为本，虚热为标，三者相互关联：失血导致阴亏，阴亏易生虚热，热又耗阴，形成本虚标实之候。", "c": [{"name": "主失血", "desc": "芤脉中空如按葱管，为血去络伤之征。原文载‘脉见芤细，芤主失血’，并述‘崩放减而未止，向有失血，内络已损’，说明芤细脉直接反映失血与络脉损伤，血失则脉道空虚，故见芤象。"}], "n": {"主失血": 1}, "a": {"17873": "主失血"}, "t": 1, "np": 0}, "pc:六+弱+迟": {"o": "六·弱迟脉总起来主阳虚气衰、肾阳亏虚之病机。迟为阳虚，弱为气衰，二者相合，反映阳气虚衰、气血不足。两尺尤甚，则病位在肾，肾阳亏虚，下焦失于温煦。阳虚不能温养腰膝，故见腰膝足肿、关节疼痛麻木，遇温暖即稍止。此属三阴经虚寒之恙，治宜温肾养肝活络。三类病机相互关联：阳虚为根本，气衰为伴随，肾虚为病位所在，共同构成虚寒证候。", "c": [{"name": "主阳虚", "desc": "迟脉主阳虚，因阳气不足，推动无力，故脉行迟慢。原文'迟为阳虚'直接点明，且六脉迟弱、两尺尤甚，说明肾阳亏虚，下焦失于温煦，故见腰膝足肿、遇温暖即稍止等虚寒之象。"}], "n": {"主阳虚": 1}, "a": {"18602": "主阳虚"}, "t": 1, "np": 0}, "pc:关+大+缓": {"o": "关·大缓脉在古籍中主要出现于以人迎气口辨内外伤的语境。其脉象缓而大，既可主外感风邪，又可主内伤不足，关键在于脉位不同：见于人迎（左手）者为外伤，见于气口（右手）者为内伤。外感风邪时，风性疏泄故脉缓，邪客肌表故脉大；内伤饮食劳役时，脾胃受损、正气不足，气口脉亦现大缓。两类病机一实一虚，均以缓大为共同脉象特征，但结合脉位与兼症可资鉴别。", "c": [{"name": "主外感风邪", "desc": "原文言“外感风邪则人迎脉缓而大”，缓大之脉见于人迎，为风邪客表之象。风性疏泄，故脉缓；邪正交争于表，故脉大。此段以人迎气口辨内外伤，明确缓大脉属外感风邪之征。"}], "n": {"主外感风邪": 1}, "a": {"19322": "主外感风邪"}, "t": 1, "np": 0}, "pc:关+沉+弱": {"o": "关·沉弱脉总起来主里虚寒证，核心病机为阳气衰微、肝气不足。沉主里、弱主虚，合而示正气内亏、阳不鼓动。原文以“沉微而弱”直释为“虚寒”，并与洪大数甚主热瘴、弦紧主瘴疟、浮紧主表实、浮缓主伤风、洪数按之不实为阳浮阴闭等脉对举，凸显其非实热、非表证、非阳浮，而是里虚寒之候。又因关部候肝，肝脉“虚而微为不及，病在内，令人胸胁胀满”，故沉弱亦主肝虚。四类病机相互关联：里虚为病位，虚寒为病性，阳衰为虚寒之根，肝虚为脏腑定位，共同构成以阳气不足、肝气内虚为核心的里虚寒证。", "c": [{"name": "主虚寒", "desc": "关部沉弱脉，沉为里、弱为虚，合而主里虚寒证。原文将“沉微而弱”明确释为“虚寒”，并与洪大数甚主热瘴、弦紧主瘴疟等实热脉对举，说明此脉所主非实热，而是阳气不足、阴寒内盛之虚寒病机。"}], "n": {"主虚寒": 1}, "a": {"19357": "主虚寒"}, "t": 1, "np": 0}, "c:紧+平": {"o": "紧平脉在肾脉中，总以紧而和缓为平，紧而失和为病。其病机可分虚实两端：太过则紧而弹石，病在外，为邪盛；不及则紧而解索，病在内，为正衰。若紧而益坚如引葛，是水湿内停之肾水；若紧硬辟辟如弹石，则是胃气已绝之死脉。诸类以肾气为本，平脉为常，太过、不及为变，肾水为病，死脉为终，层层递进，皆不离紧脉之象与肾气盛衰。", "c": [{"name": "主肾平", "desc": "原文以肾脉沉滑为平，又言喘喘累累如钩按之紧为平。紧而和缓，是肾气充足、阴阳相济之象，故主无病之平脉。"}], "n": {"主肾平": 1}, "a": {"19376": "主肾平"}, "t": 1, "np": 0}, "c:迟+结": {"o": "结迟脉总起来主寒、虚及寒虚相搏所致的中焦胃气不通之病机。原文以吐家为例，见“阳紧阴数”知寒热相搏，紧主寒、芤主虚，寒虚相搏则“脉为阴结而迟”，胃气不通而噎；趺阳脉微涩则胃气虚寒、下利吐逆、谷不得入。可见结迟脉的核心病机是寒邪与虚气相合，凝滞中焦，致胃气壅塞、升降失司。各类之间相互关联：寒为外邪或阴寒内盛，虚为胃气不足，二者相搏则气机不通，故结迟脉既主寒、主虚，更主寒虚相搏与胃气不通。临床当结合兼脉辨寒虚孰重，总以温通补虚、调畅中焦为要。", "c": [{"name": "主寒", "desc": "原文以“阳紧阴数”论吐家，紧脉主寒；又“寸口脉紧而芤，紧即为寒”，寒邪搏结中焦，胃气不通，故脉见结迟。寒性收引凝滞，致脉气往来艰涩而迟，主寒邪内盛、阳气被遏之病机。"}], "n": {"主寒": 1}, "a": {"21593": "主寒"}, "t": 1, "np": 0}, "pc:尺+弦+急": {"o": "尺·弦急脉总起来主邪盛正衰、津伤气逆及脏气衰绝之候。其病机核心在于脉失冲和，弦急为肝木偏亢或胃气败竭之象。各类之间相互关联：邪盛正衰与汗后津伤属外感病程中的逆候，反映正不胜邪；形性相违强调脉与体质不符，提示气血逆乱；脏气衰绝则为最终转归，见弦急长脉而无胃气，预后凶险。总体而言，此脉主病以正虚邪实、脏气衰败为要，尤以尺部弦急长脉属死脉范畴，警示胃气竭绝、真气耗散之危候。", "c": [{"name": "主邪盛正衰", "desc": "伤寒热盛脉浮大者生，沉小者死，因浮大示邪有外达之机；温病脉大疾者生，细小难得者死，示正能抗邪则生。脉之大小迟速与病机顺逆相关，弦急脉若见于热盛而兼细小，则正衰邪陷，预后不良。"}], "n": {"主邪盛正衰": 1}, "a": {"21824": "主邪盛正衰"}, "t": 1, "np": 0}, "pc:尺+滑+坚": {"o": "尺·滑坚脉总属里实坚积之脉，以沉坚为主，兼见滑象，主病在里、实邪内结。其类脉或沉弱主虚寒疝瘕，或沉横主积痛，或短主气虚头痛，或长主气逆足痛，或促主阳邪肩背痛，或浮盛主表邪。诸脉虽异，皆以脉象之长短、沉浮、坚弱、横促等辨病位之表里上下与病性之虚实寒热。滑坚脉本身突出坚脉主里实，滑则示痰食积滞，故总以里实积滞为核心，兼涉虚寒、气逆、表邪等，体现脉诊以脉象统病机、分表里虚实之要。", "c": [{"name": "主里实坚积", "desc": "脉沉而坚，沉主里，坚主实，故主病在里，为实邪内结。原文'寸口脉沉而坚者，曰病在中'，明言坚脉主里实，可对应积块、内结等病机。"}], "n": {"主里实坚积": 1}, "a": {"22760": "主里实坚积"}, "t": 1, "np": 0}, "pc:左+浮+弱": {"o": "左浮弱脉总属正气不足、虚多实少之候。浮为阳气外浮或邪在表，弱为气血内虚，故其病机以虚为主，或虚中夹表。具体而言，浮弱而热恶寒者，主阳气虚，治宜补气；浮弱而发热疼痛者，主邪在表，治宜疏散；左脉浮弱小于右而热者，主血虚偏甚，用药当重血药。三类之间，阳气虚与血虚同属正虚，表证则属虚中夹实；浮弱脉总以虚为本，或兼表邪，或偏气血，临证当结合兼症与左右脉大小辨治。", "c": [{"name": "主阳气虚", "desc": "浮弱脉主阳气虚。原文曰“脉浮或弱而热，或恶寒者，阳气虚也”，浮为阳气外浮，弱为正气不足，阳虚不能温煦则恶寒，虚阳外浮则发热，故浮弱并见主阳气虚，治宜补气。"}], "n": {"主阳气虚": 1}, "a": {"23973": "主阳气虚"}, "t": 1, "np": 0}, "pc:寸+涩+芤": {"o": "寸·涩芤脉在内伤胸痛辨证中主上部蓄血。芤为血虚失血之象，涩为血瘀气滞之征，二者相合，反映血虚与血瘀并存的病机，且病位偏于上部（胸膈）。原文“寸脉芤涩，上部蓄血”是直接依据。该脉所主病机单一，即上部蓄血，与滑大主痰、洪数主火、沉结主气滞等并列，共同构成内伤胸痛的不同证型。", "c": [{"name": "主蓄血", "desc": "原文“寸脉芤涩，上部蓄血”直接点明。芤脉中空如按葱管，主血虚或失血；涩脉往来艰涩，主血行瘀滞。二者并见，提示上部（胸膈）血行不畅、瘀血内停，故主上部蓄血。"}], "n": {"主蓄血": 1}, "a": {"24670": "主蓄血"}, "t": 1, "np": 0}, "pe:寸+动": {"o": "寸·动脉所主病机广泛，总以气机躁动不安为纲，可归纳为虚实两端。实证方面，动脉主燥屎内结、肝阳上冒、肺气壅闭、脾胃络病之实，皆因邪阻或阳亢致气机壅遏而脉动；虚证方面，主肾虚冲逆、脏气衰绝，因阴亏阳浮或脏气败绝而脉动无根。此外，胃气常动为生理之动，非病脉。各类之间，实者多因邪闭、热郁、阳亢，虚者多因阴亏、气衰，而脾胃络病则虚实兼见。动脉总以躁动不宁为特征，其病机或为邪扰，或为虚阳浮动，或为脏气将绝，须结合兼脉及症候辨其虚实寒热。", "c": [{"name": "主燥屎内结", "desc": "寸脉发动，关尺沉，右寸关沉涩如有物应指，尺沉数，为燥屎内结、腑气不通。动因气机被阻而躁动，数主郁热，沉涩应指如有物，原文断为燥屎，宜推下之。"}, {"name": "主肾虚冲逆", "desc": "寸静尺动，屡经失血，气从下焦上冲则呛，劳动气促。尺动为肾阴亏虚，虚阳不潜，冲气上逆，病不在肺而在肾，治宜滋肾阴以潜降冲逆。"}, {"name": "主肝阳上冒", "desc": "左寸关沉弦而横，沉为水亏，弦为肝阳亢逆，横则气机横逆。症见头痛颈脉动，肝阳上冒至巅为厥，舌生芒刺，水亏营弱，龙雷之火并发，治宜滋水潜阳。"}, {"name": "主脾胃络病", "desc": "公孙别络入络肠胃，实则胃热，阳脉大于寸口三倍，症见腹中切痛、舌强筋转；虚则胃寒，阴脉小于寸口一倍，症见鼓胀泄水。脉时缀缀动为络脉扭折之征，虚实两端皆由脾胃络脉病变。"}, {"name": "主胃气常动", "desc": "足阳明胃脉为五脏六腑之海，精气上注于肺，肺气从太阴而行，以息往来。人一呼脉再动，一吸脉再动，呼吸不已，脉动不止，此胃气充沛、肺气调和之常脉，非病脉。"}, {"name": "主脏气衰绝", "desc": "脉来如屋漏、雀啄、弹石、解索、虾游、鱼翔等怪脉，皆无胃气柔和之象。脉病人不病而见此类脉者死，说明脏气衰绝，胃气已败，生机将息。"}, {"name": "主肺气壅闭", "desc": "云门中府动脉应手，症见喉痹、胸中暴逆、咳喘不得卧、疝积上冲心。脉代不至寸口为脉气断续、阳衰不达四末，脉鼓不通为邪闭脉道、气血壅遏，病机属肺气壅闭、气血不畅。"}], "n": {"主燥屎内结": 1, "主肾虚冲逆": 3, "主肝阳上冒": 1, "主脾胃络病": 1, "主胃气常动": 1, "主脏气衰绝": 1, "主肺气壅闭": 1}, "a": {"3061": "主燥屎内结", "5732": "主肾虚冲逆", "10425": "主肝阳上冒", "10597": "主肾虚冲逆", "17938": "主肾虚冲逆", "21548": "主脾胃络病", "21616": "主胃气常动", "21823": "主脏气衰绝", "22389": "主肺气壅闭"}, "t": 9, "np": 0}, "pe:尺+实": {"o": "尺·实脉总起来主下焦邪实壅盛之证，以实为核心，病位偏里偏下。其具体所主涵盖胎孕、下焦实滞、里实积结、实热壅盛、痰湿土壅及正虚邪恋等类。胎孕为生理之实，非病邪；下焦实滞与里实积结多因燥屎、湿热、瘀血、积块搏结于下焦，气机壅阻而痛；实热壅盛则邪热与糟粕相结，或化火内实，脉见滑实、大实、数实；痰湿土壅由滑实之象提示痰饮内阻、土运太过；正虚邪恋则见于久病、汗后或脉兼细小散乱，示胃气衰败、邪实正虚。诸类之间，实脉总为邪气亢盛之象，然须结合兼脉、病程及部位判断：新病脉实为邪有外达之机，久病脉实或兼虚象则预后多不良。尺部实脉既主有形邪结，亦可见于胎孕等生理状态，临证当脉症合参，不可一概攻伐。", "c": [{"name": "主胎孕", "desc": "尺脉实可主胎孕。原文叶南洲妻经闭五月，似痨瘵而两尺脉皆实，陈斗岩断为有孕，饮清和之剂而安，后生子。尺脉主胞宫，实为胎孕之征，非虚劳之候，外受风邪搏激故有发热咳嗽等症。"}, {"name": "主下焦实滞", "desc": "尺部应下焦，实主邪壅，故尺实主下焦实滞、气机壅阻。如尺弦实主湿热瘀血搏结魄门、内痔结粪疼痛；尺沉实主下焦结粪、燥屎内停；尺实坚主里实积结、疝瘕少腹痛。皆以实为核心，病位偏下焦。"}, {"name": "主实热壅盛", "desc": "尺滑实、大实、数实皆主邪热壅盛。滑为阳脉主痰饮、主热，实为邪气亢盛，相合提示实热内结或痰阻土壅；大实主实热内盛如肾火上炎、胃火刑金；数实主邪热内盛、积滞结实。新病见之为邪有外达之机，久病则正虚邪恋。"}, {"name": "主正虚邪恋", "desc": "尺实脉须结合病程与兼脉。若汗后、久病或与细小脉交替出现，则示正虚邪恋；数紧实脉兼绝止散乱，与怪脉并列，为胃气败绝、脏气衰败之死候。此从反面界定实脉之实，提示实中夹虚、预后不良之机。"}], "n": {"主胎孕": 1, "主下焦实滞": 2, "主实热壅盛": 1, "主正虚邪恋": 3}, "a": {"4034": "主胎孕", "21807": "主下焦实滞", "21824": "主正虚邪恋", "22233": "主下焦实滞", "23716": "主正虚邪恋", "23815": "主实热壅盛", "26092": "主正虚邪恋"}, "t": 7, "np": 0}, "pe:六+促": {"o": "促脉总起来主阳盛热结、气机急促不宁之病机，其核心为热盛急迫或气机逆乱而脉行时一止。从所收段落看，促脉所主主要有四类：一为热盛，如阳明壮热、六脉洪数而促；二为痰气交结，如气口数盛而促、痰热中结；三为惊气乱，如忧恚惊怒后气机逆乱而促；四为肝风上扰，如壮火烁阴、肝风内动而六脉皆促。四类之间常相兼为病：热盛可炼液为痰，痰热交结又易引动肝风；惊怒伤肝，气乱生痰，痰气交阻亦致脉促。故促脉虽主热、痰、惊、风，总不离气机急促不宁之象，临证须脉证合参，辨其热、痰、惊、风之偏重，不可一概视为元气败绝。", "c": [{"name": "主热盛", "desc": "促脉来去急促而时一止，为阳盛热结、热势急迫之象。原文见六脉洪数而促，壮热大汗、鼻衄烦躁，断为阳明热盛，有燎原之势；又六脉皆促，面赤、痞满不食，示壮火烁阴。热邪亢盛，脉行急迫而歇止，故主热盛。"}, {"name": "主痰气交结", "desc": "促脉主气机急促不宁，痰热内结则脉促。原文气口数盛而促，患者神气愦乱、口噤目瞠、撮空，断为挟惊挟怒、痰气中结，非元气败绝；弦促脉亦主痰气交阻。痰热壅滞，气机不利，脉行急促而止，故主痰气交结。"}, {"name": "主肝风上扰", "desc": "促脉为阳盛热结兼歇止，壮火烁阴而肝风上扰。原文年逾古稀，头目眩晕，服补中益气加参后痞满不食、坐不得卧、喃喃不休、面赤、左颊聂聂𥆧动，六脉皆促，示壮火肝风之兆。热盛动风，脉促而歇，故主肝风上扰。"}], "n": {"主热盛": 1, "主痰气交结": 1, "主肝风上扰": 1}, "a": {"3559": "主肝风上扰", "3661": "主痰气交结", "5233": "主热盛", "21797": "__np"}, "t": 4, "np": 1}, "pe:右+急": {"o": "右急脉总起来主病机以虚、热、气逆、湿热、肝虚火动为主。虚证见脉急无力，为气血两虚、气随血脱；热证分数急脉之虚实，虚热与实热并见；气逆由弦急脉所示，气机郁滞、逆乱不平；湿热由缓急脉所致，湿郁气分、肝风内动；肝虚火动由细急脉所主，肝血不足、火动气逆。各类之间，急脉为共性，兼脉与部位定其具体病机，虚为本，热、逆、湿、火为标，相互关联。", "c": [{"name": "主虚", "desc": "脉急而无力，为气血两虚之象。如半产后气随血脱，脉急无力；吐血后右急关滑皆无力，为气血大亏；血崩后脉微细异常，为气随血脱。急而无力反映正气虚衰，非实热。"}], "n": {"主虚": 3}, "a": {"15442": "主虚", "15651": "主虚", "19812": "主虚"}, "t": 3, "np": 0}, "pe:关+急": {"o": "关·急脉总起来主肝木为病与火盛气逆，兼及虚脱危候。其核心病机为肝气郁结、气逆急迫，因关候中焦肝胆，急为拘急气逆之象，故情志抑郁、肝阳上亢、肝火内炽皆可见左关急或弦急；火盛则数急，阳明伏热、胃火阴亏、瘀血虚热均可致关脉数急。肝木太过则乘脾侮金，下吸肾阴，故见肝阳伤肾、咳嗽心烦等传变之候。然急脉亦有虚脱之变，如大气下陷、血脱气散时，右寸关微见如水上浮麻，左脉不见，此非实火，乃气散危候。诸类之中，肝郁气逆与火盛最为常见，肝阳伤肾为传变之果，气陷血脱则为虚极之变，临证当合参寸关左右及兼脉，辨其虚实。", "c": [{"name": "主肝郁气逆", "desc": "关脉候中焦肝胆，急为气逆急迫之象。情志抑郁则肝气不舒，气郁化火，脉见左关尤急；肝气太过，实而弦急，气逆上攻则眩运、头痛眼眩、胁支满，甚则恶言。沉急则气郁于里而逆乱，故胁支满、小便难。"}, {"name": "主肝阳伤肾", "desc": "左关尤急，两寸关俱大，因情志抑郁先见此脉，后心烦咳嗽，舌苔时黄时退。肝为受病之源，肾为传病之所，肝阳吸引肾阴，如瓶水日吸干，子虚盗母气，金不制木，木反侮金，故脉急而大。"}, {"name": "主气陷血脱", "desc": "脉右寸关微见如水上浮麻，左部脉皆不见，乃大气下陷、血脱气散之危候。急用升补大气，脉虽出而微细异常，血仍不止，呼气不能外出，欲大便，皆大气下陷之征。此急脉见于虚脱，非实火可比。"}], "n": {"主肝郁气逆": 1, "主肝阳伤肾": 1, "主气陷血脱": 1}, "a": {"15420": "主肝阳伤肾", "19357": "主肝郁气逆", "19812": "主气陷血脱"}, "t": 3, "np": 0}, "ps:右寸+软": {"o": "右寸软脉总属肺气不足、气虚不振之象，然其兼脉不同，所主病机亦异。单纯软弱或极软弱者，多主气虚，甚则气虚不能摄血；软而兼滑者，主痰浊壅肺或痰火为患；软而见于平脉，则主肺肾虚损，属不足之候；软兼滑数弦等，又主虚实夹杂，肺虚而痰火实；若左脉弦长上鱼际而右寸软弱，则为木行乘金、肝木亢逆之候。诸类之中，以气虚为本，痰、火、木亢为标，虚实夹杂者最为常见。临证当结合兼脉及症情，辨其虚多实少或实多虚少，以定补泻之宜。", "c": [{"name": "主气虚", "desc": "右寸候肺主气，软脉为气虚不振之象。原文见右寸软弱、极软弱，伴行经如崩、头晕眼花，断为气虚血热、气虚不能摄血；又右寸关虚软无力，为脾肺阳气亏虚。故软脉主气虚，尤以肺脾气虚为要。"}, {"name": "主虚损", "desc": "软脉见于右寸，常示肺气不足、肾气偏弱。原文见右寸软、尺小弱，余部中和，为肺气不足、肾气偏弱之象，然瘀尽络固、痰少神安，属平脉范畴，只宜静养。故软脉主虚损，多为肺肾两虚、气阴不足之候。"}, {"name": "主虚实夹杂", "desc": "软脉可兼见滑、数、弦等，主虚实夹杂之机。原文见右寸滑软、左脉细涩，断为肺肾并衰、出纳无权，虚实夹杂；又右寸软小不疏、关滑数、左尺濡小无力，为气火虚与痰火实并见。故软脉主虚实夹杂，尤以肺虚痰实、气火失调为多。"}, {"name": "主木乘金", "desc": "右寸软弱，左脉弦长直上鱼际，为肝木亢逆、肺金受乘之候。原文断为亢而不下之脉，《难经》所谓木行乘金，兼痰火，症见眩晕、肢节作胀。故软脉主木乘金，即肝木亢盛、肺金受侮，多兼痰火。"}], "n": {"主气虚": 2, "主虚损": 2, "主虚实夹杂": 2, "主木乘金": 2}, "a": {"2099": "主虚损", "2124": "主虚实夹杂", "6043": "主木乘金", "6047": "主气虚", "6337": "主木乘金", "6341": "主气虚", "15518": "主虚实夹杂", "15845": "主虚损"}, "t": 8, "np": 0}, "ps:右寸+紧": {"o": "右寸紧脉总主风寒之邪犯肺，属外感表证范畴。其脉浮紧，浮主邪在表，紧主寒邪束表，右寸候肺，故为风寒闭肺之象。风寒外袭，肺气失宣，可致喘咳、胸痛、寒热无汗等症；寒性收引，津液凝滞，又可兼夹痰浊，形成痰凝气滞，阻塞清道。原文所载三则，或为风寒闭肺兼痰凝气滞，或为寒邪客肺，或为风寒伤肺，皆以右寸浮紧为凭。故紧脉所主病机，以风寒闭肺为核心，痰凝气滞为常见兼夹，外感表证为其共性。三者相互关联，总不离寒邪束表、肺气壅塞之机。", "c": [{"name": "主风寒闭肺", "desc": "右寸浮紧，浮为邪在表，紧为寒邪束表。肺主气，外合皮毛，风寒客肺，肺气失宣，故见喘咳、胸脘闷、背板如缚等症。原文如“风寒闭肺”、“寒邪客肺”、“风寒伤肺”皆属此类。"}, {"name": "主外感表证", "desc": "浮紧为外感风寒之典型脉象，右寸候肺，主邪在表。原文“浮为邪在表，紧为寒邪束表”，见畏寒发热、骨节酸疼、咳嗽不已；“外感腋痛之脉”亦以右寸浮紧辨风寒伤肺。"}], "n": {"主风寒闭肺": 2, "主外感表证": 1}, "a": {"15589": "主风寒闭肺", "15906": "主风寒闭肺", "24678": "主外感表证"}, "t": 3, "np": 0}, "r:浮取": {"o": "浮取脉象所主病机广泛，总以正气盛衰与邪气性质为纲。其核心在于脉气浮越于外或浮取反应异常：虚证见浮取无力、濡弱、空豁，为气血阴阳不足；热证见浮取数、洪、滑，为热邪鼓动；痰湿证见浮取滑、濡、弦，为痰湿黏滞；风证见浮取弦、浮缓，为风性轻扬；气陷气郁见浮取不足、伏牢、举之涩，为气机失常；瘀血见浮取涩滞，为血行不畅；虚实夹杂则浮取虚细数或散乱无根。各类之间常相兼为病，如虚中夹热、痰热互结、气虚湿滞等，临证须四诊合参，以脉测机，不可执一。", "c": [{"name": "主虚（气血阴阳亏虚）", "desc": "浮取无力、濡弱、虚细、举之若无等，为气血阴阳不足之象。如脉濡弱主气虚湿滞，举之若无按之濡耎为血虚，脉洪大而空为虚阳外越，脉散为正气涣散，皆因正气不充，脉道不实，故浮取无力或空豁。"}, {"name": "主热（实热或伏热）", "desc": "浮取数、洪、滑、弦数等，主热盛或热郁。如脉数大而空为热盛阴竭，六脉俱数浮取不足沉取有余为伏热内结，脉浮弦为风热在表，脉滑搏流利为妊娠血聚有热，皆热邪鼓动气血，脉行急迫。"}, {"name": "主痰饮湿浊", "desc": "浮取滑、濡、弦滑等，主痰湿内蕴。如举之则濡按之则滑为胃火膈痰，右寸浮缓气口微滑为痰沫壅塞，脉浮弦为饮邪，脉濡数而浮为湿遏热伏，皆痰湿黏滞，脉气往来流利或濡软。"}, {"name": "主风（外风或内风）", "desc": "浮取弦、浮缓、浮数等，主风邪为病。如脉浮弦为血虚风入，脉浮缓为风中经络，脉弦而迟沉部有浮部无为阳虚内风旋动，皆风性轻扬，脉气浮越或弦急。"}, {"name": "主气陷气郁", "desc": "浮取不足、沉取有力、伏牢、举之似涩等，主气机郁滞或清阳下陷。如脉伏且牢浮取不应为火郁于内，举之似涩按之有力为气滞血瘀，脉沉细欲无为清阳下陷，皆气机失常，脉道不畅或浮取不应。"}, {"name": "主瘀血", "desc": "浮取涩、举之似涩、沉涩等，主瘀血内阻。如举之似涩按之有力为实中夹瘀，脉沉涩按之益力为痰阻血瘀，左脉浮取弦沉取宽泛为血瘀，皆瘀血阻滞，脉道不利，故涩滞不畅。"}], "n": {"主虚（气血阴阳亏虚）": 48, "主热（实热或伏热）": 6, "主痰饮湿浊": 13, "主风（外风或内风）": 5, "主气陷气郁": 10, "主瘀血": 3}, "a": {"1521": "主气陷气郁", "2020": "主虚（气血阴阳亏虚）", "2418": "主虚（气血阴阳亏虚）", "2936": "主痰饮湿浊", "2937": "主瘀血", "3005": "主虚（气血阴阳亏虚）", "3345": "主虚（气血阴阳亏虚）", "3371": "主虚（气血阴阳亏虚）", "3409": "主热（实热或伏热）", "3410": "主热（实热或伏热）", "3424": "主虚（气血阴阳亏虚）", "3495": "主虚（气血阴阳亏虚）", "3511": "主虚（气血阴阳亏虚）", "3691": "主痰饮湿浊", "3775": "主虚（气血阴阳亏虚）", "3799": "主热（实热或伏热）", "3923": "主痰饮湿浊", "4024": "主虚（气血阴阳亏虚）", "4025": "主虚（气血阴阳亏虚）", "4177": "主热（实热或伏热）", "4183": "主虚（气血阴阳亏虚）", "4238": "主虚（气血阴阳亏虚）", "4327": "主虚（气血阴阳亏虚）", "4420": "主痰饮湿浊", "5007": "主痰饮湿浊", "5279": "主瘀血", "5437": "主瘀血", "5655": "主气陷气郁", "5665": "主风（外风或内风）", "7732": "主热（实热或伏热）", "8290": "主虚（气血阴阳亏虚）", "8857": "主虚（气血阴阳亏虚）", "8981": "主风（外风或内风）", "9950": "主虚（气血阴阳亏虚）", "10399": "主虚（气血阴阳亏虚）", "11077": "主虚（气血阴阳亏虚）", "11095": "主虚（气血阴阳亏虚）", "12136": "主虚（气血阴阳亏虚）", "12173": "主气陷气郁", "12388": "主热（实热或伏热）", "13121": "主痰饮湿浊", "13277": "主虚（气血阴阳亏虚）", "13446": "主痰饮湿浊", "13883": "主虚（气血阴阳亏虚）", "14148": "主痰饮湿浊", "14302": "主痰饮湿浊", "14442": "主痰饮湿浊", "15542": "主虚（气血阴阳亏虚）", "15548": "主虚（气血阴阳亏虚）", "15576": "主虚（气血阴阳亏虚）", "15967": "主虚（气血阴阳亏虚）", "15972": "主虚（气血阴阳亏虚）", "16170": "主虚（气血阴阳亏虚）", "17292": "主痰饮湿浊", "17314": "主痰饮湿浊", "17389": "主风（外风或内风）", "17460": "__np", "17462": "__np", "18719": "主虚（气血阴阳亏虚）", "19291": "主虚（气血阴阳亏虚）", "19337": "主虚（气血阴阳亏虚）", "19436": "主气陷气郁", "19488": "主气陷气郁", "19512": "主气陷气郁", "19612": "主虚（气血阴阳亏虚）", "20375": "主气陷气郁", "20413": "主虚（气血阴阳亏虚）", "20427": "主虚（气血阴阳亏虚）", "21796": "主虚（气血阴阳亏虚）", "21797": "主虚（气血阴阳亏虚）", "22781": "主虚（气血阴阳亏虚）", "23522": "主痰饮湿浊", "23625": "主气陷气郁", "23839": "主虚（气血阴阳亏虚）", "24296": "主虚（气血阴阳亏虚）", "24618": "主风（外风或内风）", "24619": "主风（外风或内风）", "24620": "主虚（气血阴阳亏虚）", "24621": "主虚（气血阴阳亏虚）", "25216": "主虚（气血阴阳亏虚）", "25786": "主虚（气血阴阳亏虚）", "26411": "主虚（气血阴阳亏虚）", "26413": "主虚（气血阴阳亏虚）", "26809": "主虚（气血阴阳亏虚）", "26871": "主气陷气郁", "26885": "主气陷气郁", "26992": "主虚（气血阴阳亏虚）"}, "t": 87, "np": 2}, "u:歇止": {"o": "歇止脉总属脉气不能接续之象，所主病机以正虚为本，邪郁为标。其类有六：正虚邪郁者，营卫不相续；阳气衰微者，阴寒内胜；气血大虚者，脉道不充；痰火壅滞者，脉失柔和；痧毒壅滞者，脉道时阻；脏气衰败者，生气大损。诸类之间，正虚贯穿始终：阳气衰微、气血大虚、脏气衰败皆正虚之甚；正虚邪郁、痰火壅滞、痧毒壅滞则虚中挟实。歇止脉虽主虚，亦有因实邪壅滞而致者，须脉证合参，辨其虚实主次。大抵歇止脉见微迟芤虚者多虚，见不柔弦劲或迟数不定者多实，而脏气衰败者则预后不良。", "c": [{"name": "主正虚邪郁", "desc": "歇止脉见气血不能接续，正虚而邪郁，营卫不相续。如3358段六脉不至、左寸动摇为邪郁于表、阳气不达；7377段六脉皆起但仍歇止，为正虚邪郁、营卫几不相续；17598段脉象如昨示胃气未复。皆因正气亏虚，邪气阻滞，脉道断续而歇止。"}, {"name": "主阳气衰微", "desc": "歇止脉主阳气衰微、阴寒内胜。如8884段脉迟微，原文谓微为阳衰、迟为阴胜，断为脾土虚而真阳衰；3478段六脉如丝，面青唇白，为阳气衰微、气血大虚；8892段外证虽逆六脉尚存，知脉气未绝，阳气犹可挽回。脉歇止而微迟，示阳气不能鼓动血脉。"}, {"name": "主气血大虚", "desc": "歇止脉主气血大虚、脉道不充。如8857段六脉芤虚时或见涩，芤主失血，虚主气弱，涩为血行不畅，断为病久生郁大虚挟寒；14080段脉象六阴按之如无，为高年阴液枯竭、脉道不充；12703段脉来停止，为脏气衰败、气血不能接续。皆因气血亏虚，脉道失充而歇止。"}, {"name": "主痰火壅滞", "desc": "歇止脉主肝阳有余、胃阴不足，稠痰浊火扰动壅滞。如5741段脉来不柔、时自歇止，知肝阳有余而胃阴不足，稠痰浊火扰动于中、壅滞于外；17946段同文，脉不柔而歇止，示肝阳化火生痰，壅滞脉络，气血运行不畅。脉失柔和而歇止，为痰火壅滞脉道之象。"}, {"name": "主痧毒壅滞", "desc": "歇止脉主痧毒壅滞、气血运行失序。如18475段痢血日数十次，六脉或迟或数、或时歇指，迟数互见、歇指不定，为痧毒壅滞、气血运行失序、脉道时阻时通之象，非单纯痢疾之脉，故断为秋痢兼痧。脉歇止而迟数不定，示毒邪壅遏脉道。"}, {"name": "主脏气衰败", "desc": "歇止脉主脏气衰败、生气大损。如12703段年逾六旬，二气就衰，脉来停止，土败金残，生气大损，虑难奏捷；7377段歇止脉示气血断续，虽邪退而正未复，还怕里陷。脉停止而见土败金残，为脏气衰微、胃气将绝之危候，预后不良。"}], "n": {"主正虚邪郁": 8, "主阳气衰微": 4, "主气血大虚": 5, "主痰火壅滞": 2, "主痧毒壅滞": 1, "主脏气衰败": 2}, "a": {"3358": "主正虚邪郁", "3359": "主正虚邪郁", "3478": "主阳气衰微", "3832": "主阳气衰微", "4278": "主正虚邪郁", "5741": "主痰火壅滞", "6382": "主正虚邪郁", "7057": "主气血大虚", "7377": "主正虚邪郁", "7426": "主正虚邪郁", "7524": "主脏气衰败", "7565": "主正虚邪郁", "7812": "主正虚邪郁", "8857": "主气血大虚", "8884": "主阳气衰微", "8892": "主阳气衰微", "12703": "主脏气衰败", "14080": "主气血大虚", "14374": "主气血大虚", "17598": "主气血大虚", "17946": "主痰火壅滞", "18475": "主痧毒壅滞"}, "t": 22, "np": 0}, "rc:沉取+浮+虚": {"o": "沉取浮虚脉总属虚候，以气血亏虚、气不内守为核心。其沉取弱缓主气虚阳弱，浮软无力主血虚不充，浮虚按不应指则示气不内守、虚阳外浮；若见于暑热伤气，则为热伤气阴、气少浮越。四类病机相互关联：气虚则血亦不足，血虚则气失所附，气血俱虚则中气不固、脉变动无常；气不内守可致冲气上逆，热伤气阴亦令气浮于外。总以正虚为本，或兼气逆、或兼热伤，然皆不离气血虚衰、气失固守之机。", "c": [{"name": "主气虚", "desc": "沉取弱缓、浮虚无力，为气虚阳弱之象。原文谓“沉弱缓为气虚不足”，又见声哑、畏寒、食伤难消等症，皆中气不固、运化无力所致。脉变动无常亦示正气不守。"}, {"name": "主血虚", "desc": "浮软无力、按不应指，为血虚不充之征。原文谓“浮软无力为血虚不充”，兼见面色苍白、夜卧不寐、口苦舌干等，皆阴血不足、不能濡养所致。"}, {"name": "主气不内守", "desc": "浮虚脉为气不内守，虚阳外浮。原文谓“浮虚为气不内守”，又见冲气上逆、手足厥逆发呃，乃胃虚相火挟冲脉上逆，气不归元而浮越于外。"}, {"name": "主热伤气阴", "desc": "阳暑热证，火盛伤气，汗出脉虚浮，为热伤气而气少，气阴两伤。原文谓“脉虚浮主气阴两伤”，与烦渴少气相应，宜白虎加人参汤清补兼施。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主气虚": 2, "主血虚": 0, "主气不内守": 1, "主热伤气阴": 1, "其他": 0}, "a": {"3615": "主气虚", "8612": "主气不内守", "15216": "主气虚", "23169": "主热伤气阴"}, "t": 4, "np": 0}, "pc2:左寸+大+洪": {"o": "左寸大洪脉总属阳盛有余之象，主火、主痰、主瘀热，亦可因虚而见。其形成机理为阳热亢盛，气血壅涌，故脉形洪大。实者如痰火壅盛、瘀热内结，脉多洪大而数，兼滑，症见咯血、痞疼，为有余之候；心火炎上者，左寸浮洪，自汗出；虚者如水亏火旺，左尺浮洪无力，乃阴不制阳。各类之间，以火为共性，痰、瘀为兼邪，虚火为变证，总以洪大为脉形基础，辨其有力无力、兼滑兼数，以分虚实。", "c": [{"name": "主痰火", "desc": "左寸洪大，右寸关滑数，为痰火壅盛之象。原文载‘胃中痰火素盛，壅于胸膈’，症见咯血色紫、痞疼，脉洪大主火，滑主痰，数主热，痰与瘀血挟而为热，属有余之候。"}, {"name": "主瘀热", "desc": "洪大而数，兼滑，示瘀热内结。原文谓‘痰与瘀血挟而为热’，咯血色紫，胸膈痞疼，脉左寸洪大、两手尽数，为痰瘀互结化热之实证，非虚损出血。"}, {"name": "主心火", "desc": "左寸浮洪，为心火炎上之征。原文治内伤自汗，左寸脉浮洪而自汗者，属心火炎，故加麦冬、五味、川连以清心火，洪大主火，浮为阳浮。"}, {"name": "主水亏火旺", "desc": "左尺浮洪无力，为水亏火旺。原文内伤自汗案中，左尺浮洪无力，重加生地、熟地以滋水制火，洪大虽主火，无力则属虚火，由水亏不能制火所致。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主痰火": 2, "主瘀热": 0, "主心火": 0, "主水亏火旺": 1, "其他": 0}, "a": {"6055": "主痰火", "6349": "主痰火", "18419": "主水亏火旺"}, "t": 3, "np": 0}});